with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 3/1981, del Defensor del Pueblo, el Defensor del Pueblo será elegido por las Cortes Generales para un periodo de:', 'El art. 2.1 LO 3/1981 fija un mandato de cinco años.', 'gc_04_derecho_constitucional', (select id from public.topics where slug = 'gc-04-derecho-constitucional'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Art. 2.1 LO 3/1981', 'El Defensor del Pueblo será elegido por las Cortes Generales para un periodo de cinco años, y se dirigirá a las mismas a través de los Presidentes del Congreso y del senado, respectivamente.', null, '2159e385b4dba4ff56882c444290469056b5e9bfa87d69f470e28a7903480f68', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2159e385b4dba4ff56882c444290469056b5e9bfa87d69f470e28a7903480f68')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cinco años.', true), ('B', 'Cuatro años.', false), ('C', 'Seis años.', false), ('D', 'Nueve años.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
