with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 6 de la Ley Orgánica 3/1981, mientras permanezca en el ejercicio de sus funciones, la decisión sobre la inculpación, prisión, procesamiento y juicio del Defensor del Pueblo corresponde exclusivamente a:', 'El art. 6.3 LO 3/1981 reserva esas decisiones a la Sala de lo Penal del Tribunal Supremo, y solo admite su detención o retención en caso de flagrante delito.', 'gc_04_derecho_constitucional', (select id from public.topics where slug = 'gc-04-derecho-constitucional'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Art. 6.3 LO 3/1981', 'el Defensor del Pueblo no podrá ser detenido ni retenido sino en caso de flagrante delito, correspondiendo la decisión sobre su inculpación, prisión, procesamiento y juicio exclusivamente a la Sala de lo Penal del Tribunal Supremo.', null, '8282a21969a58c8263c24d3699610acf2492dd6be7dce8c593e8ad8b1c11f591', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8282a21969a58c8263c24d3699610acf2492dd6be7dce8c593e8ad8b1c11f591')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La Sala de lo Penal de la Audiencia Nacional.', false), ('B', 'El Tribunal Constitucional.', false), ('C', 'La Sala de lo Penal del Tribunal Superior de Justicia de Madrid.', false), ('D', 'La Sala de lo Penal del Tribunal Supremo.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 15 de la Ley Orgánica 3/1981, toda queja ante el Defensor del Pueblo se presentará firmada por el interesado, en escrito razonado y en el plazo máximo de:', 'El art. 15.1 LO 3/1981 fija el plazo máximo de un año desde que el interesado tuvo conocimiento de los hechos.', 'gc_04_derecho_constitucional', (select id from public.topics where slug = 'gc-04-derecho-constitucional'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-10325'), 'Art. 15.1 LO 3/1981', 'Toda queja se presentará firmada por el interesado, con indicación de su nombre, apellidos y domicilio, en escrito razonado en papel común y en el plazo máximo de un año, contado a partir del momento en que tuviera conocimiento de los hechos objeto de la misma.', null, '4100a2bfc3f94b71a83cde3c3e485b0a6bdaeeb190683a8fd63c5bd506ca65fd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '4100a2bfc3f94b71a83cde3c3e485b0a6bdaeeb190683a8fd63c5bd506ca65fd')
  returning id
), o as (
