  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un año, contado a partir del momento en que tuviera conocimiento de los hechos objeto de la misma.', true), ('B', 'Seis meses, contados desde que se produjeron los hechos.', false), ('C', 'Tres meses, contados a partir del momento en que tuviera conocimiento de los hechos.', false), ('D', 'Dos años, contados desde que se produjeron los hechos.', false)) as v(label, body, ok)
)
