with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 3 de la Ley Orgánica 1/1982, cuando el consentimiento de un menor deba otorgarse por escrito por su representante legal, este deberá ponerlo en conocimiento previo del Ministerio Fiscal, y si este se opusiere en el plazo de:', 'El art. 3.2 LO 1/1982 prevé que, si el Ministerio Fiscal se opone en el plazo de ocho días, resolverá el Juez.', 'gc_04_derecho_constitucional', (select id from public.topics where slug = 'gc-04-derecho-constitucional'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1982-11196'), 'Art. 3.2 LO 1/1982', 'En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.', null, 'c7db483d4c60959fde8a9ad41f4127c035ce0742fd19cb8e0fb377de944c4c22', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'c7db483d4c60959fde8a9ad41f4127c035ce0742fd19cb8e0fb377de944c4c22')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ocho días, resolverá el Juez.', true), ('B', 'Quince días, resolverá el Juez.', false), ('C', 'Diez días, el consentimiento quedará sin efecto definitivamente.', false), ('D', 'Ocho días, resolverá la entidad pública de protección de menores.', false)) as v(label, body, ok)
)
