  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 4 de la Ley Orgánica 1/1982, a falta de designado en testamento y de familiares legitimados, el Ministerio Fiscal podrá ejercer las acciones de protección del honor, la intimidad o la imagen de una persona fallecida siempre que no hubieren transcurrido más de:', 'El art. 4.3 LO 1/1982 limita la actuación del Ministerio Fiscal a ochenta años desde el fallecimiento.', 'gc_04_derecho_constitucional', (select id from public.topics where slug = 'gc-04-derecho-constitucional'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1982-11196'), 'Art. 4.3 LO 1/1982', 'A falta de todos ellos, el ejercicio de las acciones de protección corresponderá al Ministerio Fiscal, que podrá actuar de oficio a instancia de persona interesada, siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado.', null, '11ea366ceeb886f0abdf15d90107837cf2f2715bf7c256e31769df370877af66', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '11ea366ceeb886f0abdf15d90107837cf2f2715bf7c256e31769df370877af66')
