  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 255 del TFUE, el comité que se pronuncia sobre la idoneidad de los candidatos a juez y abogado general del Tribunal de Justicia y del Tribunal General está compuesto por:', 'El art. 255 TFUE fija un comité de siete personalidades (antiguos miembros del TJUE, miembros de órganos jurisdiccionales nacionales superiores y juristas de reconocida competencia), una de ellas propuesta por el Parlamento Europeo.', 'gc_05_union_europea', (select id from public.topics where slug = 'gc-05-union-europea'), 3, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016E/TXT'), 'Art. 255 TFUE', 'El comité estará compuesto por siete personalidades elegidas de entre antiguos miembros del Tribunal de Justicia y del Tribunal General, miembros de los órganos jurisdiccionales nacionales superiores y juristas de reconocida competencia, uno de los cuales será propuesto por el Parlamento Europeo.', null, '92b24d61faf236de542dbcd3a714fcfe7bf086bb3234ce46b02150528659ebfd', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '92b24d61faf236de542dbcd3a714fcfe7bf086bb3234ce46b02150528659ebfd')
  returning id
), o as (
