with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 13 del Tratado de la Unión Europea, ¿cuál de los siguientes órganos es una institución de la Unión?', 'El art. 13.1 TUE enumera siete instituciones: Parlamento Europeo, Consejo Europeo, Consejo, Comisión, Tribunal de Justicia de la Unión Europea, Banco Central Europeo y Tribunal de Cuentas. El Comité Económico y Social y el Comité de las Regiones son órganos consultivos (art. 13.4 TUE).', 'gc_05_union_europea', (select id from public.topics where slug = 'gc-05-union-europea'), 1, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Art. 13.1 TUE', 'Las instituciones de la Unión son: El Parlamento Europeo, El Consejo Europeo, El Consejo, La Comisión Europea (denominada en lo sucesivo «Comisión»), El Tribunal de Justicia de la Unión Europea, El Banco Central Europeo, El Tribunal de Cuentas.', null, 'acd6be703b423951eac2290c9503a9e64b890185f85b1cfdc55877c7144cb749', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'acd6be703b423951eac2290c9503a9e64b890185f85b1cfdc55877c7144cb749')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Comité Económico y Social.', false), ('B', 'El Comité de las Regiones.', false), ('C', 'El Tribunal de Cuentas.', true), ('D', 'El Defensor del Pueblo Europeo.', false)) as v(label, body, ok)
)
