with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Tratado de la Unión Europea, la función legislativa y la función presupuestaria de la Unión las ejercen conjuntamente:', 'El art. 14.1 TUE (y, en paralelo, el art. 16.1 TUE) atribuye conjuntamente al Parlamento Europeo y al Consejo la función legislativa y la presupuestaria.', 'gc_05_union_europea', (select id from public.topics where slug = 'gc-05-union-europea'), 1, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Art. 14.1 TUE', 'El Parlamento Europeo ejercerá conjuntamente con el Consejo la función legislativa y la función presupuestaria.', null, 'e27c5e76485012721073f252aa0af89a7157a197af57cead162a8843f0656870', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e27c5e76485012721073f252aa0af89a7157a197af57cead162a8843f0656870')
