  select 'Conforme al artículo 14.2 del TUE, ¿cuál es el número máximo de escaños del Parlamento Europeo que puede asignarse a un Estado miembro?', 'El art. 14.2 TUE fija un máximo de 750 diputados más el Presidente, con un mínimo de seis por Estado miembro y un máximo de noventa y seis escaños por Estado.', 'gc_05_union_europea', (select id from public.topics where slug = 'gc-05-union-europea'), 2, 'es', true, (select id from public.sources where url = 'https://eur-lex.europa.eu/legal-content/ES/TXT/?uri=CELEX:12016M/TXT'), 'Art. 14.2 TUE', 'Su número no excederá de setecientos cincuenta, más el Presidente. La representación de los ciudadanos será decrecientemente proporcional, con un mínimo de seis diputados por Estado miembro. No se asignará a ningún Estado miembro más de noventa y seis escaños.', null, '795cb8188f399d2bf7cdd93bb7976daa79057d786b5c42964f8e60f4d9b28c07', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '795cb8188f399d2bf7cdd93bb7976daa79057d786b5c42964f8e60f4d9b28c07')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Noventa y seis.', true), ('B', 'Setenta y cinco.', false), ('C', 'Cien.', false), ('D', 'Ochenta y seis.', false)) as v(label, body, ok)
)
