with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 250 del Código Civil, la medida formal de apoyo que se aplicará a quienes precisen el apoyo de modo continuado es:', 'El art. 250 CC define la curatela como medida formal para el apoyo continuado; la guarda de hecho es una medida informal y el defensor judicial procede cuando el apoyo se precisa de forma ocasional. La tutela queda reservada a los menores (art. 199).', 'gc_07_derecho_civil', (select id from public.topics where slug = 'gc-07-derecho-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1889-4763'), 'Art. 250 CC', 'La curatela es una medida formal de apoyo que se aplicará a quienes precisen el apoyo de modo continuado.', null, '81f98f56319414620f1ed7f4799eb45bb0b384a94f0db58a81a1eec36f8b8eb2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '81f98f56319414620f1ed7f4799eb45bb0b384a94f0db58a81a1eec36f8b8eb2')
  returning id
), o as (
