with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 del Código Penal, las leyes penales que favorezcan al reo:', 'El art. 2.2 CP consagra la retroactividad de la ley penal más favorable incluso con sentencia firme y condena en cumplimiento; en caso de duda sobre la ley más favorable, será oído el reo.', 'gc_08a_penal_general', (select id from public.topics where slug = 'gc-08a-penal-general'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 2.2 CP', 'No obstante, tendrán efecto retroactivo aquellas leyes penales que favorezcan al reo, aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena.', null, '833c9de3cf5be26f232ec41e377ea3d180448f4d4350ef62eaaa43ca31c908d8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '833c9de3cf5be26f232ec41e377ea3d180448f4d4350ef62eaaa43ca31c908d8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tendrán efecto retroactivo solo si aún no ha recaído sentencia firme.', false), ('B', 'Tendrán efecto retroactivo, aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena.', true), ('C', 'No tendrán en ningún caso efecto retroactivo.', false), ('D', 'Tendrán efecto retroactivo solo cuando así lo acuerde el Gobierno mediante indulto.', false)) as v(label, body, ok)
)
