  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 del Código Penal, a los efectos de determinar la ley penal aplicable en el tiempo, los delitos se consideran cometidos:', 'El art. 7 CP adopta el criterio de la actividad: el delito se entiende cometido cuando se ejecuta la acción o se omite el acto debido.', 'gc_08a_penal_general', (select id from public.topics where slug = 'gc-08a-penal-general'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 7 CP', 'A los efectos de determinar la ley penal aplicable en el tiempo, los delitos se consideran cometidos en el momento en que el sujeto ejecuta la acción u omite el acto que estaba obligado a realizar.', null, '0a4497f971d94faeb3121f648ae4a943b0bced0c32e5f9eb0fd03ca6afb1c09c', false
