with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 14.3 del Código Penal, si el error sobre la ilicitud del hecho constitutivo de la infracción penal fuera vencible:', 'El art. 14.3 CP: el error de prohibición invencible excluye la responsabilidad; el vencible rebaja la pena en uno o dos grados. La sanción como imprudente corresponde al error vencible sobre un hecho constitutivo (art. 14.1).', 'gc_08a_penal_general', (select id from public.topics where slug = 'gc-08a-penal-general'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 14.3 CP', 'El error invencible sobre la ilicitud del hecho constitutivo de la infracción penal excluye la responsabilidad criminal. Si el error fuera vencible, se aplicará la pena inferior en uno o dos grados.', null, '94bef18a4484a4aa868e24314f17d6b21a75d6ccce8adcca735ad5b1b65167e3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '94bef18a4484a4aa868e24314f17d6b21a75d6ccce8adcca735ad5b1b65167e3')
  returning id
), o as (
