with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 16.2 del Código Penal, quien evite voluntariamente la consumación del delito, bien desistiendo de la ejecución ya iniciada, bien impidiendo la producción del resultado:', 'El art. 16.2 CP regula el desistimiento voluntario: exime de la pena por la tentativa, pero no de los delitos ya consumados en los actos ejecutados.', 'gc_08a_penal_general', (select id from public.topics where slug = 'gc-08a-penal-general'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 16.2 CP', 'Quedará exento de responsabilidad penal por el delito intentado quien evite voluntariamente la consumación del delito, bien desistiendo de la ejecución ya iniciada, bien impidiendo la producción del resultado, sin perjuicio de la responsabilidad en que pudiera haber incurrido por los actos ejecutados, si éstos fueren ya constitutivos de otro delito.', null, '482ab954e54db39e8897a74423d837ffa929da4b70abef7aa79170013867f0ec', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '482ab954e54db39e8897a74423d837ffa929da4b70abef7aa79170013867f0ec')
  returning id
), o as (
