  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Será castigado con la pena inferior en uno o dos grados a la del delito consumado.', false), ('B', 'Será castigado como autor de tentativa con la atenuante de reparación del daño.', false), ('C', 'Quedará exento de toda responsabilidad penal, incluida la derivada de los actos ya ejecutados.', false), ('D', 'Quedará exento de responsabilidad penal por el delito intentado, sin perjuicio de la responsabilidad por los actos ya ejecutados si fueren constitutivos de otro delito.', true)) as v(label, body, ok)
)
