with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 20.4 del Código Penal, ¿cuáles son los requisitos de la legítima defensa?', 'El art. 20.4 CP exige agresión ilegítima, necesidad racional del medio y falta de provocación suficiente. La comparación de males es requisito del estado de necesidad (art. 20.5).', 'gc_08a_penal_general', (select id from public.topics where slug = 'gc-08a-penal-general'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 20.4 CP', 'Primero. Agresión ilegítima. […] Segundo. Necesidad racional del medio empleado para impedirla o repelerla. Tercero. Falta de provocación suficiente por parte del defensor.', null, 'd2563494241f17e7da5b463f0408681651713b6f52b62cec037f003119cca426', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd2563494241f17e7da5b463f0408681651713b6f52b62cec037f003119cca426')
  returning id
