with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 139 del Código Penal, ¿cuál de las siguientes circunstancias convierte la muerte de otro en asesinato?', 'El art. 139.1 CP enumera cuatro circunstancias: alevosía; precio, recompensa o promesa; ensañamiento; y facilitar la comisión de otro delito o evitar que se descubra. El abuso de confianza, el prevalimiento del carácter público y la reincidencia son agravantes genéricas del art. 22.', 'gc_08b_penal_especial', (select id from public.topics where slug = 'gc-08b-penal-especial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 139.1 CP', '4.ª Para facilitar la comisión de otro delito o para evitar que se descubra.', null, '7aff2649aa80928e253914db2c98566d70874412133a20b07a311e9693ce810a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7aff2649aa80928e253914db2c98566d70874412133a20b07a311e9693ce810a')
