  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 419 del Código Penal, la autoridad o funcionario público que recibiere dádiva o favor para realizar en el ejercicio de su cargo un acto contrario a los deberes inherentes al mismo incurrirá en la pena de prisión de:', 'El art. 419 CP castiga el cohecho pasivo propio con prisión de tres a seis años, multa de doce a veinticuatro meses e inhabilitación especial de nueve a doce años.', 'gc_08b_penal_especial', (select id from public.topics where slug = 'gc-08b-penal-especial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 419 CP', 'incurrirá en la pena de prisión de tres a seis años, multa de doce a veinticuatro meses, e inhabilitación especial para empleo o cargo público y para el ejercicio del derecho de sufragio pasivo por tiempo de nueve a doce años', null, '665e37cf16364c9849f17a07721744d25d037acdbc3ffbcd6dbee29033044562', false
