with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 472 del Código Penal, son reos del delito de rebelión los que se alzaren:', 'El art. 472 CP exige un alzamiento violento y público con alguno de los fines que enumera (derogar o suspender la Constitución, declarar la independencia de una parte del territorio, etc.). Ni el alzamiento clandestino o privado ni el tumultuario sin violencia reúnen los requisitos que exige este artículo.', 'gc_08b_penal_especial', (select id from public.topics where slug = 'gc-08b-penal-especial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 472 CP', 'Son reos del delito de rebelión los que se alzaren violenta y públicamente para cualquiera de los fines siguientes', null, 'cd5cf13697a1fbc8d9ede039786e63408e6f1009a1afb82b6d147dc7ee88eb0d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cd5cf13697a1fbc8d9ede039786e63408e6f1009a1afb82b6d147dc7ee88eb0d')
  returning id
), o as (
