  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Violenta y públicamente para cualquiera de los fines previstos en dicho artículo.', true), ('B', 'Pública y tumultuariamente para impedir la aplicación de las leyes.', false), ('C', 'Clandestinamente para derogar la Constitución.', false), ('D', 'Violentamente, aunque sea de forma privada, contra cualquier autoridad.', false)) as v(label, body, ok)
)
