with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 530 del Código Penal, la autoridad o funcionario público que, mediando causa por delito, prolongare la privación de libertad de un detenido con violación de los plazos o demás garantías constitucionales o legales será castigado con la pena de:', 'El art. 530 CP, dentro de los delitos cometidos por funcionarios contra las garantías constitucionales, castiga estas conductas con inhabilitación especial de cuatro a ocho años.', 'gc_08b_penal_especial', (select id from public.topics where slug = 'gc-08b-penal-especial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 530 CP', 'La autoridad o funcionario público que, mediando causa por delito, acordare, practicare o prolongare cualquier privación de libertad de un detenido, preso o sentenciado, con violación de los plazos o demás garantías constitucionales o legales, será castigado con la pena de inhabilitación especial para empleo o cargo público por tiempo de cuatro a ocho años.', null, 'b28c74e62e7714a7e9d65d2243e399d9b472bfa7b66d1bdca90359727311eec4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b28c74e62e7714a7e9d65d2243e399d9b472bfa7b66d1bdca90359727311eec4')
  returning id
), o as (
