with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 607 bis del Código Penal, son reos de delitos de lesa humanidad quienes cometan los hechos previstos en dicho artículo:', 'El art. 607 bis.1 CP caracteriza la lesa humanidad por el ataque generalizado o sistemático contra la población civil; el propósito de destruir un grupo es propio del genocidio (art. 607).', 'gc_08b_penal_especial', (select id from public.topics where slug = 'gc-08b-penal-especial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'Art. 607 bis.1 CP', 'Son reos de delitos de lesa humanidad quienes cometan los hechos previstos en el apartado siguiente como parte de un ataque generalizado o sistemático contra la población civil o contra una parte de ella.', null, 'fae30e36bf5a0c65fc29cabe75a27e9cbd14b9c4ed885c1f43d2200fc093aaa8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fae30e36bf5a0c65fc29cabe75a27e9cbd14b9c4ed885c1f43d2200fc093aaa8')
