with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 15 de la Ley de Enjuiciamiento Criminal, cuando no conste el lugar en que se haya cometido el delito y se suscite competencia entre varios jueces, ¿cuál tiene preferencia en primer lugar?', 'El art. 15 LECrim enumera cuatro fueros subsidiarios (pruebas materiales, aprehensión, residencia del reo y noticia del delito) y ordena que la competencia se decida dando preferencia por ese mismo orden, por lo que prima el lugar donde se descubrieron pruebas materiales.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 15 LECrim', '1.º El del término municipal, partido o circunscripción en que se hayan descubierto pruebas materiales del delito. […] Si se suscitase competencia entre estos Jueces o Tribunales, se decidirá dando la preferencia por el orden con que están expresados en los números que preceden.', null, 'ee80483d733a38b4a5c4892984fabc669ee52d9f65145ee00823bb95fd6b9b29', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ee80483d733a38b4a5c4892984fabc669ee52d9f65145ee00823bb95fd6b9b29')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El del término municipal, partido o circunscripción en que se hayan descubierto pruebas materiales del delito.', true), ('B', 'El del término municipal, partido o circunscripción en que el presunto reo haya sido aprehendido.', false), ('C', 'El de la residencia del reo presunto.', false), ('D', 'Cualquiera que hubiese tenido noticia del delito.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select '¿Cuál de los siguientes se considera delito conexo a efectos de la atribución de jurisdicción y de la distribución de la competencia, según el artículo 17.2 de la Ley de Enjuiciamiento Criminal?', 'El art. 17.2.4.º LECrim incluye entre los delitos conexos los cometidos para procurar la impunidad de otros delitos; los cometidos por varias personas en distintos lugares o tiempos solo son conexos si precedió concierto (17.2.2.º), y los de una misma persona con analogía o relación no son conexos, aunque puedan enjuiciarse juntos (17.3).', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 17.2 LECrim', '2. A los efectos de la atribución de jurisdicción y de la distribución de la competencia se consideran delitos conexos: […] 4.º Los cometidos para procurar la impunidad de otros delitos.', null, '8e61cd466508ec82bf6e9b9cf0b21ad8fd6620e8dc8c6edf6febf86c01284ab1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8e61cd466508ec82bf6e9b9cf0b21ad8fd6620e8dc8c6edf6febf86c01284ab1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los cometidos por dos o más personas en distintos lugares o tiempos sin que haya precedido concierto para ello.', false), ('B', 'Los cometidos para procurar la impunidad de otros delitos.', true), ('C', 'Los cometidos por la misma persona aunque no tengan analogía ni relación entre sí.', false), ('D', 'Los cometidos por una misma persona en distintos partidos judiciales contra víctimas diferentes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 102 de la Ley de Enjuiciamiento Criminal, con las salvedades que el propio artículo establece, no podrá ejercitar la acción penal:', 'El art. 102 LECrim excluye del ejercicio de la acción penal a quien no goce de la plenitud de los derechos civiles, al condenado dos veces por sentencia firme por denuncia o querella calumniosas y al Juez o Magistrado (aunque pueden ejercerla por delitos contra sus personas o bienes o los de ciertos familiares).', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 102 LECrim', 'no podrán ejercitar la acción penal: 1.º El que no goce de la plenitud de los derechos civiles. 2.º El que hubiera sido condenado dos veces por sentencia firme como reo del delito de denuncia o querella calumniosas. 3.º El Juez o Magistrado.', null, '34287c7b90738efc6c8e562e1c28dd61e89122d0323c25c7bef98dd18b6d9006', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '34287c7b90738efc6c8e562e1c28dd61e89122d0323c25c7bef98dd18b6d9006')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El funcionario de la Policía Judicial.', false), ('B', 'El abogado en ejercicio.', false), ('C', 'El que hubiera sido condenado una vez por sentencia firme por cualquier delito.', false), ('D', 'El Juez o Magistrado.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 115 de la Ley de Enjuiciamiento Criminal, ¿qué efecto produce la muerte del culpable sobre las acciones nacidas del delito?', 'El art. 115 LECrim dispone que la acción penal se extingue por la muerte del culpable, mientras que la civil subsiste contra herederos y causahabientes, ejercitable solo ante la jurisdicción civil.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 115 LECrim', 'La acción penal se extingue por la muerte del culpable; pero en este caso subsiste la civil contra sus herederos y causahabientes, que sólo podrá ejercitarse ante la jurisdicción y por la vía de lo civil.', null, '3609ae42313c17deb67e4563c5da4bddf4d41d4f81034d7faa66b880efe93051', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3609ae42313c17deb67e4563c5da4bddf4d41d4f81034d7faa66b880efe93051')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se extinguen tanto la acción penal como la civil.', false), ('B', 'Subsisten la acción penal y la civil, que podrán dirigirse contra sus herederos.', false), ('C', 'Se extingue la acción penal, pero subsiste la civil contra sus herederos y causahabientes, que solo podrá ejercitarse ante la jurisdicción y por la vía de lo civil.', true), ('D', 'Se extingue la acción penal, pero la civil subsiste y puede seguir ejercitándose ante el juez penal que conocía de la causa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 123 de la Ley de Enjuiciamiento Criminal, ¿qué documentos deberán ser traducidos en todo caso al imputado o acusado que no hable o entienda el castellano o la lengua oficial de la actuación?', 'El art. 123.1.d) LECrim reconoce el derecho a la traducción escrita de los documentos esenciales para la defensa y precisa que siempre deben traducirse las resoluciones que acuerden la prisión, el escrito de acusación y la sentencia.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 123.1.d) LECrim', 'Deberán ser traducidos, en todo caso, las resoluciones que acuerden la prisión del imputado, el escrito de acusación y la sentencia.', null, '57a03f63fa113b6b976c741dbc2e0e059aa4df3ed48497aef3eba0f838776753', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '57a03f63fa113b6b976c741dbc2e0e059aa4df3ed48497aef3eba0f838776753')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La denuncia, el atestado policial y la sentencia.', false), ('B', 'La querella, el auto de procesamiento y la citación a juicio.', false), ('C', 'Únicamente la sentencia firme.', false), ('D', 'Las resoluciones que acuerden la prisión del imputado, el escrito de acusación y la sentencia.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 126 de la Ley de Enjuiciamiento Criminal, ¿qué derechos del artículo 123.1 no podrán ser renunciados en ningún caso por el imputado o acusado?', 'El art. 126 LECrim admite la renuncia expresa, libre e informada a los derechos del art. 123, salvo los de las letras a) (intérprete en todas las actuaciones en que sea necesaria su presencia) y c) (interpretación de todo el juicio oral), que son irrenunciables.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 126 LECrim', 'En todo caso, los derechos a los que se refieren las letras a) y c) del apartado 1 del artículo 123 no podrán ser renunciados.', null, '7d38a27e802afb77b9fdf0d291b2b2ef44aed56360ddc37fc6359b488eaa86b2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7d38a27e802afb77b9fdf0d291b2b2ef44aed56360ddc37fc6359b488eaa86b2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El de ser asistido por un intérprete en las actuaciones en que sea necesaria su presencia y el de interpretación de todas las actuaciones del juicio oral.', true), ('B', 'El de traducción escrita de los documentos esenciales y el de presentar una solicitud motivada para que se considere esencial un documento.', false), ('C', 'El de servirse de intérprete en las conversaciones con su abogado y el de traducción escrita de la sentencia.', false), ('D', 'Todos ellos pueden renunciarse, siempre que la renuncia sea expresa y libre.', false)) as v(label, body, ok)
)
