with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 261 de la Ley de Enjuiciamiento Criminal, con carácter general no están obligados a denunciar los parientes colaterales del delincuente:', 'El art. 261 LECrim exime de la obligación de denunciar al cónyuge o persona en análoga relación de afectividad, a ascendientes y descendientes y a los colaterales hasta el segundo grado inclusive, salvo en los delitos graves contra menores o personas con discapacidad necesitadas de especial protección que el propio artículo enumera.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 261 LECrim', '2.º Quienes sean ascendientes y descendientes del delincuente y sus parientes colaterales hasta el segundo grado inclusive.', null, 'a3e561fffed2aabc2ebaa097ce3561fe5945df7db567cdd359811cc28a4b0a63', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a3e561fffed2aabc2ebaa097ce3561fe5945df7db567cdd359811cc28a4b0a63')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Hasta el tercer grado inclusive.', false), ('B', 'Hasta el segundo grado inclusive.', true), ('C', 'Hasta el cuarto grado inclusive.', false), ('D', 'Hasta el cuarto grado por consanguinidad y el segundo por afinidad.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 266 de la Ley de Enjuiciamiento Criminal, ¿en cuál de los siguientes casos no se podrá presentar la denuncia por vía telemática?', 'El art. 266 LECrim excluye la denuncia telemática si el hecho se cometió con violencia o intimidación, si tiene autor conocido, si hay testigos, si el denunciante es menor de edad, si hay delito flagrante o si los hechos son de naturaleza violenta o sexual; la denuncia telemática se firma con firma electrónica.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 266 LECrim', 'No se podrán denunciar por vía telemática aquellos hechos que se hayan producido con violencia o intimidación, ni si tienen autor conocido, ni si existen testigos, ni si el denunciante es menor de edad, ni si se ha cometido delito flagrante, ni aquellos hechos de naturaleza violenta o sexual.', null, '6b9e456555840229dfa6f26acee8cc93a6218df6caef6669e0f2aa7cf15f0dc8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6b9e456555840229dfa6f26acee8cc93a6218df6caef6669e0f2aa7cf15f0dc8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cuando se trate de un hecho sin autor conocido ni testigos, cometido sin violencia ni intimidación.', false), ('B', 'Cuando la denuncia se firme con firma electrónica.', false), ('C', 'Cuando el denunciante sea menor de edad.', true), ('D', 'Cuando el denunciante resida fuera del partido judicial en que se cometió el hecho.', false)) as v(label, body, ok)
)
