  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 277 de la Ley de Enjuiciamiento Criminal, la querella se presentará siempre:', 'A diferencia de la denuncia, la querella exige postulación: el art. 277 LECrim impone su presentación por Procurador con poder bastante y la firma de Letrado.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 277 LECrim', 'La querella se presentará siempre por medio de Procurador con poder bastante y suscrita por Letrado.', null, '8b57a6ef9e68819fbd2590338c5d21af0cf9597bc5e6fc4f853603f244df031d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '8b57a6ef9e68819fbd2590338c5d21af0cf9597bc5e6fc4f853603f244df031d')
  returning id
), o as (
