with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 284.2 de la Ley de Enjuiciamiento Criminal, cuando no exista autor conocido del delito, la Policía Judicial conservará el atestado sin enviarlo a la autoridad judicial ni al Ministerio Fiscal, salvo, entre otros casos:', 'El art. 284.2 LECrim exceptúa de la conservación del atestado sin autor conocido los delitos contra la vida, la integridad física, la libertad e indemnidad sexuales y los relacionados con la corrupción, los casos en que se practique una diligencia con resultado pasadas setenta y dos horas y aquellos en que el Fiscal o el juez soliciten la remisión.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 284.2 LECrim', 'a) Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción;', null, 'f2813048824ee9db430d0064414d2247068a82c18fe486dfca39d463ce5c5b26', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f2813048824ee9db430d0064414d2247068a82c18fe486dfca39d463ce5c5b26')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que se trate de delitos contra el patrimonio cometidos sin violencia ni intimidación.', false), ('B', 'Que hayan transcurrido veinticuatro horas desde la apertura del atestado.', false), ('C', 'Que se trate de delitos contra la vida, contra la integridad física, contra la libertad e indemnidad sexuales o de delitos relacionados con la corrupción.', true), ('D', 'Que el denunciante lo solicite por escrito.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 295 de la Ley de Enjuiciamiento Criminal, salvo fuerza mayor y el supuesto del artículo 284.2, los funcionarios de Policía Judicial no podrán dejar transcurrir sin dar conocimiento a la autoridad judicial o al Ministerio Fiscal de las diligencias practicadas más de:', 'El art. 295 LECrim fija en veinticuatro horas el plazo máximo para dar conocimiento de las diligencias practicadas, y castiga disciplinariamente tanto su superación como la demora innecesaria dentro de ese plazo.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 295 LECrim', 'En ningún caso los funcionarios de Policía Judicial podrán dejar transcurrir más de veinticuatro horas sin dar conocimiento a la autoridad judicial o al Ministerio Fiscal de las diligencias que hubieran practicado, salvo en los supuestos de fuerza mayor y en el previsto en el apartado 2 del artículo 284.', null, '3ba1967ffe3fabd1f7ebeadd530f6a55c558049fa2866db7e9221d4385ac98a5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3ba1967ffe3fabd1f7ebeadd530f6a55c558049fa2866db7e9221d4385ac98a5')
  returning id
), o as (
