  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Doce horas.', false), ('B', 'Cuarenta y ocho horas.', false), ('C', 'Setenta y dos horas.', false), ('D', 'Veinticuatro horas.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
