  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No superior a tres meses, debiendo alzarse el secreto con al menos diez días de antelación a la conclusión del sumario.', false), ('B', 'No superior a un mes, debiendo alzarse el secreto con al menos diez días de antelación a la conclusión del sumario.', true), ('C', 'No superior a quince días, debiendo alzarse el secreto con al menos cinco días de antelación a la conclusión del sumario.', false), ('D', 'No superior a dos meses, sin necesidad de alzarlo antes de la conclusión del sumario.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 496 de la Ley de Enjuiciamiento Criminal, el particular, Autoridad o agente de Policía judicial que detuviere a una persona deberá ponerla en libertad o entregarla al Juez más próximo al lugar de la detención:', 'El art. 496 LECrim establece el plazo de veinticuatro horas para la entrega al juez más próximo o la puesta en libertad, y la demora superior a ese plazo genera responsabilidad penal.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 496 LECrim', 'deberá ponerla en libertad o entregarla al Juez más próximo al lugar en que hubiere hecho la detención dentro de las veinticuatro horas siguientes al acto de la misma.', null, '419f3a78711eb97f428ab6bc25e8b49bc3a91e82a774efac99b5018beb4a5a58', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '419f3a78711eb97f428ab6bc25e8b49bc3a91e82a774efac99b5018beb4a5a58')
  returning id
), o as (
