)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 520 de la Ley de Enjuiciamiento Criminal, la detención preventiva no podrá durar más del tiempo estrictamente necesario y, en todo caso, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial en el plazo máximo de:', 'El art. 520.1 LECrim (en línea con el art. 17.2 CE) fija en setenta y dos horas el límite máximo de la detención preventiva antes de la libertad o la puesta a disposición judicial.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.1 LECrim', 'Dentro de los plazos establecidos en la presente Ley, y, en todo caso, en el plazo máximo de setenta y dos horas, el detenido deberá ser puesto en libertad o a disposición de la autoridad judicial.', null, '20a714de05647a87d23b06ef5b43e35493e55dcc0372bbc6469687f66dd4df2d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '20a714de05647a87d23b06ef5b43e35493e55dcc0372bbc6469687f66dd4df2d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Veinticuatro horas.', false), ('B', 'Cuarenta y ocho horas.', false), ('C', 'Setenta y dos horas.', true), ('D', 'Noventa y seis horas.', false)) as v(label, body, ok)
)
