with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 520.5 de la Ley de Enjuiciamiento Criminal, el abogado designado para asistir al detenido acudirá al centro de detención con la máxima premura, siempre dentro del plazo máximo de:', 'El art. 520.5 LECrim impone al abogado un plazo máximo de tres horas desde que recibe el encargo; si no comparece, el Colegio de Abogados designa un nuevo abogado de oficio.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 520.5 LECrim', 'El abogado designado acudirá al centro de detención con la máxima premura, siempre dentro del plazo máximo de tres horas desde la recepción del encargo.', null, '722cdf2620ebdad6b240e5fb8b6f08d37743783f51512be3107d684e19d86ab9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '722cdf2620ebdad6b240e5fb8b6f08d37743783f51512be3107d684e19d86ab9')
