)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A efectos de la entrada y registro, ¿cuál de los siguientes se reputa domicilio según el artículo 554 de la Ley de Enjuiciamiento Criminal?', 'El art. 554 LECrim considera domicilio los Palacios Reales, la vivienda del español o extranjero residente, los buques nacionales mercantes y la sede de dirección de las personas jurídicas imputadas; los buques del Estado, los locales de reunión o recreo y los edificios oficiales son lugares públicos según el art. 547.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1882-6036'), 'Art. 554 LECrim', 'Se reputan domicilio, para los efectos de los artículos anteriores: […] 3.º Los buques nacionales mercantes.', null, '586796370aefed14b0fd2eadee9b2a8ba2cadd0434d131ddd975ca89f9a4ae62', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '586796370aefed14b0fd2eadee9b2a8ba2cadd0434d131ddd975ca89f9a4ae62')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los buques del Estado.', false), ('B', 'Los edificios destinados a cualquier establecimiento de reunión o recreo.', false), ('C', 'Los edificios destinados a cualquier servicio oficial del Municipio.', false), ('D', 'Los buques nacionales mercantes.', true)) as v(label, body, ok)
)
