insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de «Habeas Corpus» (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-09a-lecrim', 'Tema 9. Derecho procesal penal (I): LECrim y habeas corpus') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-09a-lecrim' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley Orgánica 6/1984, reguladora del procedimiento de «Habeas Corpus», es competente para conocer de la solicitud, con carácter general:', 'El art. 2 LOHC atribuye la competencia al Juez de Instrucción del lugar donde se encuentre el privado de libertad; solo si no consta, al del lugar de la detención y, en defecto de ambos, al del lugar de las últimas noticias sobre su paradero.', 'gc_09a_lecrim', (select id from public.topics where slug = 'gc-09a-lecrim'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'Art. 2 LO 6/1984', 'Es competente para conocer la solicitud de «Habeas Corpus» el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad; si no constare, el del lugar en que se produzca la detención', null, '9b3b97da833aeb443287c7962285816d4b77d8a52c4a7f3fb34d50a47f8413cb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9b3b97da833aeb443287c7962285816d4b77d8a52c4a7f3fb34d50a47f8413cb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
