insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-09b-lopj-policia-judicial' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley 4/2015, del Estatuto de la víctima del delito, sus disposiciones se aplican a las víctimas de delitos cometidos en España o que puedan ser perseguidos en España:', 'El art. 1 de la Ley 4/2015 fija un ámbito universal: la ley protege a toda víctima de delitos cometidos o perseguibles en España, sin distinguir por nacionalidad, edad ni situación administrativa.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 1 Ley 4/2015', 'a las víctimas de delitos cometidos en España o que puedan ser perseguidos en España, con independencia de su nacionalidad, de si son mayores o menores de edad o de si disfrutan o no de residencia legal.', null, '15b4b6ce2fb744443e31dc97e460344a03cf556539893b26f83971d15158228a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '15b4b6ce2fb744443e31dc97e460344a03cf556539893b26f83971d15158228a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Con independencia de su nacionalidad, de si son mayores o menores de edad o de si disfrutan o no de residencia legal.', true), ('B', 'Siempre que tengan la nacionalidad española o de un Estado miembro de la Unión Europea.', false), ('C', 'Siempre que disfruten de residencia legal en España.', false), ('D', 'Siempre que sean mayores de edad o estén emancipadas.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 2 de la Ley 4/2015, del Estatuto de la víctima del delito, ¿a quién no serán aplicables las disposiciones de esta Ley?', 'El art. 2 de la Ley 4/2015 distingue la víctima directa (quien sufre el daño directamente causado por el delito) y la indirecta (familiares en caso de muerte o desaparición), y excluye expresamente a los terceros perjudicados.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-4606'), 'Art. 2 Ley 4/2015', 'Las disposiciones de esta Ley no serán aplicables a terceros que hubieran sufrido perjuicios derivados del delito.', null, '9b49b0cb0a570c4f13549f691309e6732b6350588591a9aa252868c52da44cf4', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9b49b0cb0a570c4f13549f691309e6732b6350588591a9aa252868c52da44cf4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la persona física que haya sufrido daños emocionales directamente causados por la comisión de un delito.', false), ('B', 'Al cónyuge no separado legalmente ni de hecho de la persona fallecida a consecuencia directa de un delito.', false), ('C', 'A terceros que hubieran sufrido perjuicios derivados del delito.', true), ('D', 'A los hijos de la víctima fallecida a consecuencia directa de un delito que convivieran con ella en el momento de la muerte.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
