with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 del Real Decreto 769/1987, sobre regulación de la Policía Judicial, constituyen la Policía Judicial en sentido estricto:', 'El art. 7 RD 769/1987 reserva el concepto de Policía Judicial en sentido estricto a las Unidades Orgánicas del art. 30.1 LOFCS, integradas por guardias civiles y policías nacionales; las funciones generales de policía judicial corresponden a todos los miembros de las FCS (art. 1).', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-14578'), 'Art. 7 RD 769/1987', 'Constituyen la Policía Judicial en sentido estricto las Unidades Orgánicas previstas en el artículo 30.1 de la Ley Orgánica de Fuerzas y Cuerpos de Seguridad integradas por miembros del Cuerpo Nacional de Policía y de la Guardia Civil.', null, '7dfc7ec7b40b1d2ad54c965df15b868b9413c20941e81b0551f3a900af3dbad6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '7dfc7ec7b40b1d2ad54c965df15b868b9413c20941e81b0551f3a900af3dbad6')
  returning id
