  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Todos los miembros de las Fuerzas y Cuerpos de Seguridad, cualquiera que sea su naturaleza y dependencia.', false), ('B', 'Las unidades especializadas de las Policías Locales de los municipios de más de 50.000 habitantes.', false), ('C', 'Las Unidades Orgánicas previstas en el artículo 30.1 de la Ley Orgánica de Fuerzas y Cuerpos de Seguridad, integradas por miembros del Cuerpo Nacional de Policía y de la Guardia Civil.', true), ('D', 'Los funcionarios enumerados en el artículo 283 de la Ley de Enjuiciamiento Criminal.', false)) as v(label, body, ok)
)
