  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El Presidente del Tribunal Supremo y del Consejo General del Poder Judicial.', true), ('B', 'El Ministro del Interior.', false), ('C', 'El Ministro de Justicia.', false), ('D', 'El Fiscal General del Estado.', false)) as v(label, body, ok)
)
