  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 38 del Real Decreto 769/1987, ¿con qué periodicidad se reúnen las Comisiones de Coordinación de la Policía Judicial?', 'El art. 38 RD 769/1987 exige a la Comisión Nacional al menos una reunión trimestral y a las Provinciales reuniones mensuales, convocadas por su Presidente.', 'gc_09b_lopj_policia_judicial', (select id from public.topics where slug = 'gc-09b-lopj-policia-judicial'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-14578'), 'Art. 38 RD 769/1987', 'La Comisión Nacional celebrará, al menos, una reunión trimestral. Las Comisiones Provinciales se reunirán con periodicidad mensual, a convocatoria de su Presidente que fijará el orden del día.', null, '6d85e27954f6477227d4953d64098ae2b2a4692f8f5f7c8c7620e83377588ec5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6d85e27954f6477227d4953d64098ae2b2a4692f8f5f7c8c7620e83377588ec5')
  returning id
), o as (
