with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 de la Ley 39/2015, ¿tienen capacidad de obrar ante las Administraciones Públicas los menores de edad?', 'El art. 3.b) LPAC reconoce capacidad de obrar a los menores para los derechos e intereses que el ordenamiento les permite ejercer sin asistencia de quien ejerza la patria potestad, tutela o curatela, salvo los menores incapacitados en lo que afecte la incapacitación.', 'gc_10a_procedimiento_administrativo', (select id from public.topics where slug = 'gc-10a-procedimiento-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 3.b) LPAC', 'b) Los menores de edad para el ejercicio y defensa de aquellos de sus derechos e intereses cuya actuación esté permitida por el ordenamiento jurídico sin la asistencia de la persona que ejerza la patria potestad, tutela o curatela.', null, 'b510943ee17018381e2940e9cf3da152a0f06099639afed4b1e69a773cd2cee1', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b510943ee17018381e2940e9cf3da152a0f06099639afed4b1e69a773cd2cee1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sí, en cualquier procedimiento, a partir de los dieciséis años.', false), ('B', 'No; solo pueden actuar a través de su representante legal.', false), ('C', 'Solo cuando la ley lo declare expresamente, igual que los grupos de afectados.', false), ('D', 'Sí, para el ejercicio y defensa de aquellos de sus derechos e intereses cuya actuación esté permitida por el ordenamiento jurídico sin la asistencia de quien ejerza la patria potestad, tutela o curatela.', true)) as v(label, body, ok)
)
