  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 5.6 de la Ley 39/2015, la falta o insuficiente acreditación de la representación no impedirá que se tenga por realizado el acto, siempre que se aporte aquella o se subsane el defecto dentro del plazo que deberá conceder el órgano administrativo, que será de:', 'El art. 5.6 LPAC permite subsanar la falta de acreditación de la representación en el plazo de diez días (o superior si las circunstancias lo exigen) que debe conceder el órgano.', 'gc_10a_procedimiento_administrativo', (select id from public.topics where slug = 'gc-10a-procedimiento-administrativo'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 5.6 LPAC', 'siempre que se aporte aquélla o se subsane el defecto dentro del plazo de diez días que deberá conceder al efecto el órgano administrativo, o de un plazo superior cuando las circunstancias del caso así lo requieran.', null, 'e98bb5c861da6459eb6a5e8ccaea79209f71fd7ff066bc606ea13bbe708ef176', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e98bb5c861da6459eb6a5e8ccaea79209f71fd7ff066bc606ea13bbe708ef176')
  returning id
