  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 39 de la Ley 39/2015, excepcionalmente podrá otorgarse eficacia retroactiva a los actos administrativos:', 'El art. 39.3 LPAC admite la retroactividad excepcional de los actos que sustituyen a otros anulados y de los favorables, si los supuestos de hecho ya existían en la fecha a que se retrotrae la eficacia y no se lesionan derechos o intereses legítimos de terceros.', 'gc_10a_procedimiento_administrativo', (select id from public.topics where slug = 'gc-10a-procedimiento-administrativo'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'Art. 39.3 LPAC', 'Excepcionalmente, podrá otorgarse eficacia retroactiva a los actos cuando se dicten en sustitución de actos anulados, así como cuando produzcan efectos favorables al interesado, siempre que los supuestos de hecho necesarios existieran ya en la fecha a que se retrotraiga la eficacia del acto y ésta no lesione derechos o intereses legítimos de otras personas.', null, '78ec427c2ef0311d49daa22a840d0761488bd7e5326173a7ffe857b027ee41d9', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '78ec427c2ef0311d49daa22a840d0761488bd7e5326173a7ffe857b027ee41d9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
