  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 29 de la Ley 50/1997, del Gobierno, en la redacción dada por la disposición final tercera de la Ley 40/2015, todos los actos y omisiones del Gobierno están sometidos al control político de:', 'El art. 29 de la Ley del Gobierno somete toda su actuación a la Constitución y al ordenamiento, atribuye el control político a las Cortes Generales y permite impugnar sus actos ante la jurisdicción contencioso-administrativa y ante el Tribunal Constitucional. El texto consolidado vigente de la Ley 50/1997 mantiene esta redacción.', 'gc_10b_regimen_juridico', (select id from public.topics where slug = 'gc-10b-regimen-juridico'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10566'), 'DF 3.ª LRJSP (art. 29.2 Ley 50/1997)', '2. Todos los actos y omisiones del Gobierno están sometidos al control político de las Cortes Generales.', null, 'ebb7eddd0e540f8f40b27911151b57ad044836aa7e2b2849d29533b4d6074c70', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'ebb7eddd0e540f8f40b27911151b57ad044836aa7e2b2849d29533b4d6074c70')
