with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 3 de la Ley Orgánica 3/2018, cuando la persona fallecida hubiese prohibido expresamente el acceso a sus datos, ¿qué podrán seguir haciendo sus herederos?', 'El art. 3.1 LO 3/2018 permite al fallecido prohibir el acceso, la rectificación o la supresión de sus datos, pero esa prohibición no afecta al derecho de los herederos a acceder a los datos de carácter patrimonial.', 'gc_11_proteccion_datos', (select id from public.topics where slug = 'gc-11-proteccion-datos'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2018-16673'), 'Art. 3.1 LOPDGDD', 'Como excepción, las personas a las que se refiere el párrafo anterior no podrán acceder a los datos del causante, ni solicitar su rectificación o supresión, cuando la persona fallecida lo hubiese prohibido expresamente o así lo establezca una ley. Dicha prohibición no afectará al derecho de los herederos a acceder a los datos de carácter patrimonial del causante.', null, '2a1b56cc4a047c40ec5e2400fd5c0cf2b58e532cc6e479e154c46a84e9d095c3', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2a1b56cc4a047c40ec5e2400fd5c0cf2b58e532cc6e479e154c46a84e9d095c3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Acceder a todos sus datos personales, pero no rectificarlos ni suprimirlos.', false), ('B', 'Acceder a los datos de carácter patrimonial del causante.', true), ('C', 'Solicitar la supresión de sus datos, pero no acceder a ellos.', false), ('D', 'Nada, porque la prohibición del fallecido impide cualquier acceso sin excepción.', false)) as v(label, body, ok)
)
