  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 del Real Decreto 207/2024, de estructura orgánica básica del Ministerio del Interior, el mando superior de las Fuerzas y Cuerpos de Seguridad del Estado corresponde a:', 'El art. 1.2 RD 207/2024 atribuye a la persona titular del Ministerio el mando superior de las Fuerzas y Cuerpos de Seguridad del Estado; a la Secretaría de Estado de Seguridad le corresponde el ejercicio del mando (art. 2.1.b) y a los Directores Generales, el mando directo de cada Cuerpo (arts. 3.1 y 4.1).', 'gc_14_ministerio_interior', (select id from public.topics where slug = 'gc-14-ministerio-interior'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2024-3793'), 'Art. 1.2 RD 207/2024', 'Corresponde a la persona titular del Ministerio la dirección de todos los servicios del Departamento, el mando superior de las Fuerzas y Cuerpos de Seguridad del Estado', null, '1bf24e1cbd00552a88b9578bae456bbde1c1d8d65557eb00dc6ec0a4fccd48c0', false
