with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 7 de la Ley Orgánica 2/1986, la Guardia Civil tendrá la consideración de fuerza armada:', 'El art. 7.3 LO 2/1986 limita la consideración de fuerza armada de la Guardia Civil al cumplimiento de las misiones de carácter militar que se le encomienden.', 'gc_15a_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'gc-15a-fuerzas-cuerpos-seguridad'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 7.3 LO 2/1986', '3. La Guardia Civil sólo tendrá consideración de fuerza armada en el cumplimiento de las misiones de carácter militar que se le encomienden, de acuerdo con el ordenamiento jurídico.', null, '117e622a25d899415e65dcb0fff7ca47bcbe413cccbb7fd5aadbd88cf746f90c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '117e622a25d899415e65dcb0fff7ca47bcbe413cccbb7fd5aadbd88cf746f90c')
