with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 9 de la Ley Orgánica 2/1986, en tiempo de guerra y durante el estado de sitio la Guardia Civil dependerá exclusivamente:', 'El art. 9.b) LO 2/1986 dispone que la Guardia Civil depende del Ministro del Interior y del de Defensa según sus funciones, pero en tiempo de guerra y durante el estado de sitio depende exclusivamente del Ministro de Defensa.', 'gc_15a_fuerzas_cuerpos_seguridad', (select id from public.topics where slug = 'gc-15a-fuerzas-cuerpos-seguridad'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1986-6859'), 'Art. 9.b LO 2/1986', 'En tiempo de guerra y durante el estado de sitio, dependerá exclusivamente del Ministro de Defensa.', null, '528e5dddf63f69241e2156c1ebdcab9e49df6089a7cb1f4cc3846c34d942b8ac', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '528e5dddf63f69241e2156c1ebdcab9e49df6089a7cb1f4cc3846c34d942b8ac')
