  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En las capitales de provincia y en los términos municipales que determine el Gobierno.', false), ('B', 'Únicamente en los municipios de menos de 20.000 habitantes.', false), ('C', 'Exclusivamente en las vías interurbanas, costas y fronteras.', false), ('D', 'En el resto del territorio nacional y su mar territorial, no reservado al Cuerpo Nacional de Policía.', true)) as v(label, body, ok)
)
