  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 8 de la Ley Orgánica 11/2007, los guardias civiles que asistan a manifestaciones o reuniones:', 'El art. 8.3 LO 11/2007 prohíbe en todo caso asistir a manifestaciones o reuniones con uniforme o portando armas y exige respetar la neutralidad propia de la condición de guardia civil.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Art. 8.3 LO 11/2007', '3. En todo caso no podrán asistir a manifestaciones o reuniones vistiendo el uniforme reglamentario, ni portando armas y deberán respetar las exigencias de neutralidad propias de la condición de Guardia Civil.', null, 'b95fbaebba1a31fde79c3f9f2a0d7fa1356a8b2552fcfa876e09b2073338db13', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b95fbaebba1a31fde79c3f9f2a0d7fa1356a8b2552fcfa876e09b2073338db13')
  returning id
