  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley Orgánica 11/2007, ¿cuál de los siguientes derechos no podrán ejercer los guardias civiles?', 'El art. 11 LO 11/2007 excluye el derecho de sindicación; en cambio, reconoce el de asociación (art. 9), el de petición individual (art. 13) y el acceso al Defensor del Pueblo (art. 14).', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Art. 11 LO 11/2007', 'Los Guardias Civiles no podrán ejercer el derecho de sindicación.', null, 'f92223f28a7c809b8bf16af2db1ebcae18f333f34ccbd039bb9c98c0488eb5ef', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f92223f28a7c809b8bf16af2db1ebcae18f333f34ccbd039bb9c98c0488eb5ef')
  returning id
