  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 20 de la Ley Orgánica 11/2007, en los casos de declaración de los estados de alarma, excepción o sitio, los guardias civiles:', 'El art. 20 LO 11/2007 regula el deber de cooperación en caso de catástrofe: presentarse en la dependencia de destino o en la más próxima y ponerse a disposición inmediata de las autoridades.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Art. 20 LO 11/2007', 'En los casos de declaración de los estados de alarma, excepción o sitio, o cuando así se disponga en caso de alteración grave de la seguridad ciudadana, emergencia grave, situación de urgente riesgo o calamidad pública, los Guardias Civiles se presentarán en su dependencia de destino o en la más próxima y se pondrán a disposición inmediata de las autoridades correspondientes.', null, 'b40f453bc32cec97abb9913889c50361716ad021610e2d9727588daf545ed41f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b40f453bc32cec97abb9913889c50361716ad021610e2d9727588daf545ed41f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se presentarán en su dependencia de destino o en la más próxima y se pondrán a disposición inmediata de las autoridades correspondientes.', true), ('B', 'Permanecerán en su domicilio a la espera de instrucciones de su unidad.', false), ('C', 'Se presentarán exclusivamente en la Dirección General de la Guardia Civil.', false), ('D', 'Se pondrán a disposición del Ministro de Defensa en el plazo de veinticuatro horas.', false)) as v(label, body, ok)
)
