  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 39 de la Ley Orgánica 11/2007, en relación con la afiliación a las asociaciones profesionales de guardias civiles, señale la respuesta correcta:', 'El art. 39 LO 11/2007 limita la afiliación a una sola asociación (39.4), formada exclusivamente por miembros del Cuerpo (39.2), y excluye a los alumnos que no tengan la condición de guardia civil (39.3).', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Art. 39.3-4 LO 11/2007', '3. Los alumnos de centros docentes de la Guardia Civil que no ostenten la condición de Guardia Civil no podrán asociarse. 4. Sólo se podrá estar afiliado a una asociación profesional.', null, 'f6972d8506de7a6741e5b6ad19a342f8e37661ecb926d767cd20b831d7103739', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f6972d8506de7a6741e5b6ad19a342f8e37661ecb926d767cd20b831d7103739')
