with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 56 de la Ley Orgánica 11/2007, la duración del mandato de los representantes de los guardias civiles en el Consejo de la Guardia Civil será de:', 'El art. 56.8 LO 11/2007 fija un mandato de cuatro años con reelección posible; se pierde la condición de representante al pasar a situación distinta del servicio activo.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-18391'), 'Art. 56.8 LO 11/2007', '8. La duración del mandato de los representantes será de cuatro años, pudiendo ser reelegidos en sucesivos procesos electorales.', null, '1e4f0cb6f51e244acc75981535b942956c9e45b36b7e1f71dd8ff68f2867e8d8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '1e4f0cb6f51e244acc75981535b942956c9e45b36b7e1f71dd8ff68f2867e8d8')
