with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 de la Ley 29/2014, de Régimen del Personal de la Guardia Civil, la condición de guardia civil se adquiere:', 'El art. 3.2 Ley 29/2014 vincula la condición de guardia civil a la obtención del primer empleo, conferido por el Rey y refrendado por el Ministro de Defensa, y a la incorporación a la escala; el juramento o promesa es un requisito previo (art. 4), no la causa de adquisición.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12408'), 'Art. 3.2 Ley 29/2014', '2. La condición de guardia civil se adquiere al obtener el primer empleo, conferido por el Rey y refrendado por el Ministro de Defensa, e incorporarse a la escala correspondiente del Cuerpo.', null, 'd608430df46c7b8caf394a1d6cd75cdd8df1946c92c8ed81e87456b225ba8217', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd608430df46c7b8caf394a1d6cd75cdd8df1946c92c8ed81e87456b225ba8217')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al superar las pruebas de selección para el ingreso en el centro docente de formación.', false), ('B', 'Al obtener el primer empleo, conferido por el Ministro del Interior y refrendado por el Director General de la Guardia Civil.', false), ('C', 'Al obtener el primer empleo, conferido por el Rey y refrendado por el Ministro de Defensa, e incorporarse a la escala correspondiente del Cuerpo.', true), ('D', 'Al prestar juramento o promesa ante la Bandera, con independencia de la obtención del primer empleo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con las reglas de comportamiento del guardia civil del artículo 7 de la Ley 29/2014, al hacer un empleo legítimo de la fuerza, sus primeras armas serán:', 'La regla 4.ª del art. 7.1 Ley 29/2014 exige un uso gradual y proporcionado de la fuerza, «siendo la persuasión y la fuerza moral sus primeras armas».', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12408'), 'Art. 7.1 Ley 29/2014', '4. Hará un empleo legítimo de la fuerza, con un uso gradual y proporcionado de la misma, siendo la persuasión y la fuerza moral sus primeras armas.', null, 'c139e963248521417e57b17b54a0e046ce7a45f40fcb9ab9b4217fcdd1e40a32', false
