  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 13 de la Ley 29/2014, ¿qué órgano, como órgano colegiado asesor y consultivo, debe ser oído en los procedimientos disciplinarios que afecten al personal del Cuerpo, de conformidad con la Ley Orgánica 12/2007?', 'El art. 13.1.c) Ley 29/2014 asigna al Consejo Superior de la Guardia Civil, órgano asesor y consultivo de los Ministros, del Secretario de Estado de Seguridad y del Director General, la función de ser oído en los procedimientos disciplinarios.', 'gc_15b_personal_guardia_civil', (select id from public.topics where slug = 'gc-15b-personal-guardia-civil'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2014-12408'), 'Art. 13.1 Ley 29/2014', '1. Al Consejo Superior de la Guardia Civil, como órgano colegiado asesor y consultivo de los Ministros de Defensa y del Interior, del Secretario de Estado de Seguridad y del Director General de la Guardia Civil, le corresponde: […] c) Ser oído en los procedimientos disciplinarios que afecten al personal del Cuerpo, de conformidad con lo previsto en la Ley Orgánica 12/2007, de 22 de octubre, de Régimen Disciplinario de la Guardia Civil.', null, 'a784317fdf619e256eba0d301b7ba0113587eafa85ea3a5ac7b543b7f1cacee7', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'a784317fdf619e256eba0d301b7ba0113587eafa85ea3a5ac7b543b7f1cacee7')
