with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 8 de la Ley 42/2007, en el Consejo Estatal para el Patrimonio Natural y la Biodiversidad, las Comunidades Autónomas y la representación de las entidades locales se integran:', 'El art. 8 Ley 42/2007 crea el Consejo Estatal como órgano de participación pública e integra en él, con voz pero sin voto, a las Comunidades Autónomas y a una representación de las entidades locales.', 'gc_16_proteccion_civil_medio_ambiente', (select id from public.topics where slug = 'gc-16-proteccion-civil-medio-ambiente'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-21490'), 'Art. 8 Ley 42/2007', 'Se crea el Consejo Estatal para el Patrimonio Natural y la Biodiversidad, como órgano de participación pública en el ámbito de la conservación y el uso sostenible del patrimonio natural y la biodiversidad, que informará, entre otros, las normas y planes de ámbito estatal relativas al patrimonio natural y la biodiversidad, y en el que se integrarán, con voz pero sin voto, las Comunidades autónomas y una representación de las entidades locales', null, 'b6e6840760576e37585dd54caf845721d1e47004755917877ebca39833cd3727', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b6e6840760576e37585dd54caf845721d1e47004755917877ebca39833cd3727')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Con voz y voto.', false), ('B', 'Con voto de calidad.', false), ('C', 'Con voz pero sin voto.', true), ('D', 'Solo como observadores, sin voz ni voto.', false)) as v(label, body, ok)
)
