with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 30 de la Ley 42/2007, ¿cuál de las siguientes figura entre las categorías de clasificación de los espacios naturales protegidos?', 'El art. 30 Ley 42/2007 clasifica los espacios naturales protegidos en Parques, Reservas Naturales, Áreas Marinas Protegidas, Monumentos Naturales y Paisajes Protegidos; las ZEPA y los LIC integran la Red Natura 2000 (art. 42) y las Reservas de la Biosfera son una figura de la UNESCO (art. 68).', 'gc_16_proteccion_civil_medio_ambiente', (select id from public.topics where slug = 'gc-16-proteccion-civil-medio-ambiente'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-21490'), 'Art. 30 Ley 42/2007', 'a) Parques. b) Reservas Naturales. c) Áreas Marinas Protegidas. d) Monumentos Naturales. e) Paisajes Protegidos.', null, 'e1ec42d5a181c69ee74ea185847c9ce7a701e43cec0ff2417fc3ff044462d6f0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'e1ec42d5a181c69ee74ea185847c9ce7a701e43cec0ff2417fc3ff044462d6f0')
