  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 43 de la Ley 42/2007, una vez aprobadas o ampliadas por la Comisión Europea las listas de Lugares de Importancia Comunitaria, estos serán declarados por las Administraciones competentes como Zonas Especiales de Conservación lo antes posible y como máximo en un plazo de:', 'El art. 43.3 Ley 42/2007 fija un máximo de seis años para declarar los LIC como ZEC, junto con su plan o instrumento de gestión; el plazo de seis meses del art. 43.2 se refiere a la publicación de los límites tras el envío de la propuesta de LIC.', 'gc_16_proteccion_civil_medio_ambiente', (select id from public.topics where slug = 'gc-16-proteccion-civil-medio-ambiente'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-21490'), 'Art. 43.3 Ley 42/2007', '3. Una vez aprobadas o ampliadas las listas de LIC por la Comisión Europea, éstos serán declarados por las Administraciones competentes, como ZEC lo antes posible y como máximo en un plazo de seis años, junto con la aprobación del correspondiente plan o instrumento de gestión.', null, '6e8430ea8bd3c12818f71a4367ef8df0f9cf1013203e6c51e3a860a085c9ab2f', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '6e8430ea8bd3c12818f71a4367ef8df0f9cf1013203e6c51e3a860a085c9ab2f')
