  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 58 de la Ley 42/2007, los taxones o poblaciones incluidos en el Catálogo Español de Especies Amenazadas se clasifican en las categorías de:', 'El art. 58.1 Ley 42/2007 establece dos categorías en el Catálogo: «en peligro de extinción» y «vulnerable»; las comunidades autónomas pueden crear otras en sus propios catálogos (58.3).', 'gc_16_proteccion_civil_medio_ambiente', (select id from public.topics where slug = 'gc-16-proteccion-civil-medio-ambiente'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-21490'), 'Art. 58.1 Ley 42/2007', 'a) En peligro de extinción: taxones o poblaciones cuya supervivencia es poco probable si los factores causales de su actual situación siguen actuando. b) Vulnerable: taxones o poblaciones que corren el riesgo de pasar a la categoría anterior en un futuro inmediato si los factores adversos que actúan sobre ellos no son corregidos.', null, 'f9cd6211232f8bc67bb6e2a52cba75a3972a7a95b23594633181e9a3ed044942', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'f9cd6211232f8bc67bb6e2a52cba75a3972a7a95b23594633181e9a3ed044942')
