insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-16-proteccion-civil-medio-ambiente' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley 17/2015, del Sistema Nacional de Protección Civil, la protección civil es:', 'El art. 1.1 Ley 17/2015 define la protección civil como instrumento de la política de seguridad pública y servicio público que protege a las personas y bienes frente a emergencias y catástrofes naturales o de origen humano, accidental o intencionado.', 'gc_16_proteccion_civil_medio_ambiente', (select id from public.topics where slug = 'gc-16-proteccion-civil-medio-ambiente'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7730'), 'Art. 1.1 Ley 17/2015', '1. La protección civil, como instrumento de la política de seguridad pública, es el servicio público que protege a las personas y bienes garantizando una respuesta adecuada ante los distintos tipos de emergencias y catástrofes originadas por causas naturales o derivadas de la acción humana, sea ésta accidental o intencionada.', null, '26d10ead37b2f8d8d6cabc5c6467a08ef420c32e72a1deb138b59de860445845', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '26d10ead37b2f8d8d6cabc5c6467a08ef420c32e72a1deb138b59de860445845')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un servicio público que, como instrumento de la política de seguridad pública, protege a las personas y bienes ante emergencias y catástrofes.', true), ('B', 'Una función exclusiva de las Fuerzas Armadas en caso de catástrofe.', false), ('C', 'Un servicio privado de interés general, prestado por entidades de voluntariado bajo la supervisión del Estado.', false), ('D', 'Un instrumento de la política de defensa nacional que se activa únicamente durante los estados de alarma, excepción y sitio.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con las definiciones del artículo 2 de la Ley 17/2015, se entiende por «riesgo»:', 'El art. 2.4 Ley 17/2015 define el riesgo como la posibilidad de que una amenaza llegue a afectar a personas o bienes; los distractores reproducen las definiciones de peligro (2.1), vulnerabilidad (2.2) y amenaza (2.3).', 'gc_16_proteccion_civil_medio_ambiente', (select id from public.topics where slug = 'gc-16-proteccion-civil-medio-ambiente'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-7730'), 'Art. 2.4 Ley 17/2015', '4. Riesgo. Es la posibilidad de que una amenaza llegue a afectar a colectivos de personas o a bienes.', null, 'cd391c1cef74cd671c1daaee84849f2dd4bf9ef24ffe6798eeaca81541f1f1fb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'cd391c1cef74cd671c1daaee84849f2dd4bf9ef24ffe6798eeaca81541f1f1fb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El potencial de ocasionar daño en determinadas situaciones a colectivos de personas o bienes.', false), ('B', 'La característica de una colectividad de personas o bienes que los hace susceptibles de ser afectados por un peligro.', false), ('C', 'La posibilidad de que una amenaza llegue a afectar a colectivos de personas o a bienes.', true), ('D', 'La situación en la que personas y bienes están expuestos a un peligro inminente o latente.', false)) as v(label, body, ok)
)
