with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 58 de la Ley 11/2022, los operadores que suministren redes públicas de comunicaciones electrónicas o que presten servicios de comunicaciones interpersonales basados en numeración disponibles al público o servicios de acceso a internet:', 'El art. 58.2 Ley 11/2022 obliga a esos operadores a realizar las interceptaciones autorizadas judicialmente conforme a la LECrim, la LO 2/2002 y otras normas con rango de ley orgánica, y a adoptar a su costa las medidas previstas.', 'gc_17_tecnologias_informacion', (select id from public.topics where slug = 'gc-17-tecnologias-informacion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757'), 'Art. 58.2 Ley 11/2022', '2. Los operadores que suministren redes públicas de comunicaciones electrónicas o que presten servicios de comunicaciones interpersonales basados en numeración disponibles al público o servicios de acceso a internet están obligados a realizar las interceptaciones que se autoricen judicialmente […] Asimismo, deberán adoptar a su costa las medidas que se establecen en este artículo y en los reglamentos correspondientes.', null, '5b4b8925eb0f84dea2d482219743f7fb599517d86f00b3ad6a55d38d0a2e5f75', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5b4b8925eb0f84dea2d482219743f7fb599517d86f00b3ad6a55d38d0a2e5f75')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Solo están obligados a realizar interceptaciones cuando lo ordene el Ministerio del Interior.', false), ('B', 'Están obligados a realizar interceptaciones autorizadas judicialmente, pero con cargo a los Presupuestos Generales del Estado.', false), ('C', 'No pueden realizar interceptaciones en ningún caso, por el secreto de las comunicaciones.', false), ('D', 'Están obligados a realizar las interceptaciones que se autoricen judicialmente y a adoptar a su costa las medidas que establece el artículo.', true)) as v(label, body, ok)
)
