with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 60 de la Ley 11/2022, en caso de violación de los datos personales, el operador de servicios de comunicaciones electrónicas disponibles al público la notificará:', 'El art. 60.3 Ley 11/2022 obliga a notificar la violación sin dilaciones indebidas a la AEPD y, si puede afectar negativamente a la intimidad o a los datos de un abonado o particular, también a este sin dilaciones indebidas.', 'gc_17_tecnologias_informacion', (select id from public.topics where slug = 'gc-17-tecnologias-informacion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757'), 'Art. 60.3 Ley 11/2022', '3. En caso de violación de los datos personales, el operador de servicios de comunicaciones electrónicas disponibles al público notificará sin dilaciones indebidas dicha violación a la Agencia Española de Protección de Datos.', null, '019953e8e8a4a3645381f70a976090badaa13cd3fad81dbb4cebeeb60aee5370', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '019953e8e8a4a3645381f70a976090badaa13cd3fad81dbb4cebeeb60aee5370')
  returning id
), o as (
