with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 62 de la Ley 11/2022, la información que se transmita por redes de comunicaciones electrónicas:', 'El art. 62 Ley 11/2022 permite proteger cualquier tipo de información mediante cifrado y lo define como instrumento de seguridad de la información, aunque puede imponerse la obligación de facilitar los algoritmos en casos justificados.', 'gc_17_tecnologias_informacion', (select id from public.topics where slug = 'gc-17-tecnologias-informacion'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-10757'), 'Art. 62.1-2 Ley 11/2022', '1. Cualquier tipo de información que se transmita por redes de comunicaciones electrónicas podrá ser protegida mediante procedimientos de cifrado. 2. El cifrado es un instrumento de seguridad de la información.', null, '0ffa0ee3e49066957ff03ef2f18d27e8d84f2ad66c2a519fa0c6d34507458f08', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0ffa0ee3e49066957ff03ef2f18d27e8d84f2ad66c2a519fa0c6d34507458f08')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No podrá cifrarse salvo autorización previa del Ministerio del Interior.', false), ('B', 'Solo podrá cifrarse cuando se trate de comunicaciones de las Administraciones públicas.', false), ('C', 'Deberá cifrarse obligatoriamente en todo caso.', false), ('D', 'Podrá ser protegida mediante procedimientos de cifrado, que es un instrumento de seguridad de la información.', true)) as v(label, body, ok)
)
