with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Conforme al artículo 7 de la Ley 6/2020, podrá prescindirse de la personación de la persona física que solicite un certificado cualificado:', 'El art. 7.1 Ley 6/2020 exige la personación ante los encargados de verificar la identidad, salvo que la firma en la solicitud haya sido legitimada notarialmente; el art. 7.2 remite a una orden ministerial los métodos de identificación a distancia.', 'gc_17_tecnologias_informacion', (select id from public.topics where slug = 'gc-17-tecnologias-informacion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046'), 'Art. 7.1 Ley 6/2020', '1. La identificación de la persona física que solicite un certificado cualificado exigirá su personación ante los encargados de verificarla y se acreditará mediante el Documento Nacional de Identidad, pasaporte u otros medios admitidos en Derecho. Podrá prescindirse de la personación de la persona física que solicite un certificado cualificado si su firma en la solicitud de expedición de un certificado cualificado ha sido legitimada en presencia notarial.', null, '5bc653f2cb59d0ca49be86ad6797b60d1732d21caa69d45c07c19a92c72c4d9e', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5bc653f2cb59d0ca49be86ad6797b60d1732d21caa69d45c07c19a92c72c4d9e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Si presenta una fotocopia compulsada de su Documento Nacional de Identidad.', false), ('B', 'Si es mayor de sesenta y cinco años o tiene reconocida una discapacidad.', false), ('C', 'Si la solicitud se presenta en una oficina de asistencia en materia de registros.', false), ('D', 'Si su firma en la solicitud de expedición ha sido legitimada en presencia notarial.', true)) as v(label, body, ok)
)
