with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 9 de la Ley 6/2020, los prestadores cualificados de servicios electrónicos de confianza que no pertenezcan al sector público deberán constituir un seguro de responsabilidad civil por importe mínimo de:', 'El art. 9.3.b) Ley 6/2020 exige un seguro mínimo de 1.500.000 euros (salvo prestadores del sector público), más 500.000 euros por cada tipo de servicio cualificado adicional; puede sustituirse por aval bancario o seguro de caución.', 'gc_17_tecnologias_informacion', (select id from public.topics where slug = 'gc-17-tecnologias-informacion'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046'), 'Art. 9.3.b Ley 6/2020', 'b) Constituir un seguro de responsabilidad civil por importe mínimo de 1.500.000 euros, excepto si el prestador pertenece al sector público. Si presta más de un servicio cualificado de los previstos en el Reglamento (UE) 910/2014, se añadirán 500.000 euros más por cada tipo de servicio.', null, '567fba0231e57afce656b82a81f7c285cb2446b09af64ccabbeedb1c96692676', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '567fba0231e57afce656b82a81f7c285cb2446b09af64ccabbeedb1c96692676')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '3.000.000 euros, con independencia del número de servicios prestados.', false), ('B', '1.500.000 euros, añadiendo 500.000 euros más por cada tipo de servicio cualificado adicional que presten.', true), ('C', '1.000.000 euros, añadiendo 250.000 euros por cada servicio adicional.', false), ('D', '500.000 euros, añadiendo 1.500.000 euros si prestan más de un servicio cualificado.', false)) as v(label, body, ok)
)
