  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 12 de la Ley 6/2020, los prestadores de servicios de confianza no cualificados:', 'El art. 12 Ley 6/2020 exime a los prestadores no cualificados de verificación previa, pero les obliga a comunicar su actividad en el plazo de tres meses desde su inicio, así como las modificaciones y el cese.', 'gc_17_tecnologias_informacion', (select id from public.topics where slug = 'gc-17-tecnologias-informacion'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2020-14046'), 'Art. 12 Ley 6/2020', 'Los prestadores de servicios de confianza no cualificados no necesitan verificación administrativa previa de cumplimiento de requisitos para iniciar su actividad, pero deberán comunicar su actividad al Ministerio de Asuntos Económicos y Transformación Digital en el plazo de tres meses desde que la inicien', null, '89097f45d51f92e41a81b64b2b610100c4a6a90de7606ee078ed544d48722f41', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '89097f45d51f92e41a81b64b2b610100c4a6a90de7606ee078ed544d48722f41')
  returning id
), o as (
