  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 3 del Real Decreto 176/2022, además del personal sujeto al régimen de derechos y deberes del Cuerpo, el Código de Conducta se aplica a:', 'El art. 3 RD 176/2022 limita el ámbito personal al personal sujeto al régimen de derechos y deberes del Cuerpo y al alumnado de los centros docentes de formación para el acceso directo a ambas escalas.', 'gc_19_deontologia', (select id from public.topics where slug = 'gc-19-deontologia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-3477'), 'Art. 3 RD 176/2022', 'El Código de Conducta será de aplicación a: a) El personal de la Guardia Civil que se encuentre sujeto al régimen de derechos y deberes de los miembros del Cuerpo. b) El alumnado de los centros docentes de formación para la incorporación por acceso directo a la Escala de Oficiales y a la Escala de Cabos y Guardias de la Guardia Civil.', null, '67623f3f5cc7b1e76ac336b24d00ba23a5ee792a8a32d4697bc6f88a160de9a6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '67623f3f5cc7b1e76ac336b24d00ba23a5ee792a8a32d4697bc6f88a160de9a6')
