with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 3 del Código de Conducta del personal de la Guardia Civil, la lealtad:', 'El art. 3 del Código de Conducta exige fidelidad, respeto y sinceridad hacia los demás componentes del Cuerpo, independientemente de su empleo, situación o destino, y declara la lealtad recíproca entre superiores y subordinados.', 'gc_19_deontologia', (select id from public.topics where slug = 'gc-19-deontologia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-3477'), 'Art. 3 Código de Conducta (RD 176/2022)', 'Mostrarán el máximo compromiso personal de fidelidad, respeto y sinceridad hacia los demás componentes del Cuerpo, independientemente de su empleo, situación o destino. La lealtad será recíproca entre los superiores jerárquicos y sus subordinados.', null, 'd579884fd93f822372ba0705ddfb884ccbb4bf44cd8e192fe5a6ae766b9de68c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd579884fd93f822372ba0705ddfb884ccbb4bf44cd8e192fe5a6ae766b9de68c')
  returning id
