with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el Código de Conducta del personal de la Guardia Civil, los guardias civiles llevarán a cabo su actividad profesional con lealtad:', 'El art. 10.1 del Código de Conducta (Defensa de la Constitución) exige la defensa de la Constitución y la actividad profesional con lealtad al Rey y respeto al ordenamiento jurídico.', 'gc_19_deontologia', (select id from public.topics where slug = 'gc-19-deontologia'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-3477'), 'Art. 10.1 Código de Conducta (RD 176/2022)', 'Mostrarán una disposición permanente para la defensa de la Constitución Española como norma fundamental del Estado y llevarán a cabo su actividad profesional con lealtad al Rey y con absoluto respeto al resto del ordenamiento jurídico, cumpliendo y haciendo cumplir la ley.', null, '20ae4c777c206e884bc9be189901967bc7e4236403179d9fc7aefcb6d339cc15', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '20ae4c777c206e884bc9be189901967bc7e4236403179d9fc7aefcb6d339cc15')
