  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 43 del Código de Conducta del personal de la Guardia Civil, solamente podrán utilizar las armas de fuego en las situaciones en que exista:', 'El art. 43.2 del Código de Conducta limita el uso de las armas de fuego al riesgo racionalmente grave para la vida o integridad propia o de terceros, o al grave riesgo para la seguridad ciudadana, conforme a los principios de congruencia, oportunidad y proporcionalidad.', 'gc_19_deontologia', (select id from public.topics where slug = 'gc-19-deontologia'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2022-3477'), 'Art. 43.2 Código de Conducta (RD 176/2022)', '2. Solamente podrán utilizar las armas de fuego en las situaciones en que exista un riesgo racionalmente grave para su vida, su integridad física o la de terceras personas, o en aquellas circunstancias que puedan suponer un grave riesgo para la seguridad ciudadana', null, '45ee16984cae3022cc65ddcc3cc1235b3378fc305eb6fe16c3abb7434f9aa13c', false
