with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley Orgánica 5/2000, reguladora de la responsabilidad penal de los menores, esta ley se aplica para exigir la responsabilidad de las personas:', 'El art. 1.1 LO 5/2000 fija su ámbito en las personas mayores de catorce años y menores de dieciocho que cometan hechos tipificados como delitos en el Código Penal o en las leyes penales especiales.', 'gc_20_menores', (select id from public.topics where slug = 'gc-20-menores'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'Art. 1.1 LO 5/2000', '1. Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de catorce años y menores de dieciocho por la comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales.', null, 'fba659321e22c515b8c2f24d0aaf893d39779607182d212969538c8f2eabc25d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'fba659321e22c515b8c2f24d0aaf893d39779607182d212969538c8f2eabc25d')
