with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con la Ley Orgánica 5/2000, ¿qué órgano es competente para conocer de los delitos previstos en los artículos 571 a 580 del Código Penal (terrorismo) cometidos por menores?', 'El art. 2.4 LO 5/2000 atribuye al Juzgado Central de Menores de la Audiencia Nacional los delitos de los arts. 571 a 580 CP; la regla general (art. 2.3) es el Juez de Menores del lugar de comisión.', 'gc_20_menores', (select id from public.topics where slug = 'gc-20-menores'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'Art. 2.4 LO 5/2000', '4. La competencia para conocer de los delitos previstos en los artículos 571 a 580 del Código Penal corresponderá al Juzgado Central de Menores de la Audiencia Nacional.', null, '9a72d480e1d86858b5852030005220711d6e051652e4eed4776f7af10fe50688', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9a72d480e1d86858b5852030005220711d6e051652e4eed4776f7af10fe50688')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
