)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 5/2000, cuando el autor de un hecho delictivo sea menor de catorce años:', 'El art. 3 LO 5/2000 excluye la responsabilidad de los menores de catorce años y remite a las normas de protección de menores; el Fiscal remite testimonio a la entidad pública de protección.', 'gc_20_menores', (select id from public.topics where slug = 'gc-20-menores'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'Art. 3 LO 5/2000', 'Cuando el autor de los hechos mencionados en los artículos anteriores sea menor de catorce años, no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores previstas en el Código Civil y demás disposiciones vigentes.', null, 'd61fc55c9ea721f546b580ea332448550f1c4401e90b07db5a7bef0ca35dad92', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd61fc55c9ea721f546b580ea332448550f1c4401e90b07db5a7bef0ca35dad92')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se le aplicarán exclusivamente las medidas de amonestación o libertad vigilada.', false), ('B', 'Responderá conforme al Código Penal con la atenuante de minoría de edad.', false), ('C', 'No se le exigirá responsabilidad con arreglo a dicha ley, sino que se le aplicarán las normas sobre protección de menores del Código Civil y demás disposiciones vigentes.', true), ('D', 'Se le podrá imponer internamiento terapéutico, como única medida posible.', false)) as v(label, body, ok)
)
