with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 10 de la Ley Orgánica 5/2000, si un menor de dieciséis o diecisiete años comete un delito de los artículos 138 o 139 del Código Penal, el Juez deberá imponer una medida de internamiento en régimen cerrado de:', 'El art. 10.2.b) LO 5/2000 fija de uno a ocho años de internamiento cerrado más libertad vigilada con asistencia educativa de hasta cinco años para los de 16-17 años; para los de 14-15 años (letra a) es de uno a cinco años más hasta tres de libertad vigilada.', 'gc_20_menores', (select id from public.topics where slug = 'gc-20-menores'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'Art. 10.2.b) LO 5/2000', 'b) Si al tiempo de cometer los hechos el menor tuviere dieciséis o diecisiete años de edad, una medida de internamiento en régimen cerrado de uno a ocho años de duración, complementada en su caso por otra de libertad vigilada con asistencia educativa de hasta cinco años.', null, '122d664fa18aacd54efd7afaa18da7b045a1fbdf7a23b3f4ddf1864c517dbc1a', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '122d664fa18aacd54efd7afaa18da7b045a1fbdf7a23b3f4ddf1864c517dbc1a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Uno a ocho años, complementada en su caso por otra de libertad vigilada con asistencia educativa de hasta cinco años.', true), ('B', 'Uno a cinco años, complementada en su caso por otra de libertad vigilada de hasta tres años.', false), ('C', 'Uno a seis años, complementada sucesivamente con libertad vigilada de hasta cinco años.', false), ('D', 'Dos a diez años, sin posibilidad de libertad vigilada complementaria.', false)) as v(label, body, ok)
)
