with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 17 de la Ley Orgánica 5/2000, la detención de un menor por funcionarios de policía no podrá durar más del tiempo estrictamente necesario y, en todo caso, dentro del plazo máximo de:', 'El art. 17.4 LO 5/2000 fija un máximo de 24 horas de detención policial del menor, tras las cuales debe ser puesto en libertad o a disposición del Ministerio Fiscal, que resolverá dentro de las 48 horas desde la detención (art. 17.5).', 'gc_20_menores', (select id from public.topics where slug = 'gc-20-menores'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'Art. 17.4 LO 5/2000', 'en todo caso, dentro del plazo máximo de veinticuatro horas, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal.', null, '9146af9420f2458e2d706be4158d5fc27266680d2d7b2a98162658ce3f4fdf2d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '9146af9420f2458e2d706be4158d5fc27266680d2d7b2a98162658ce3f4fdf2d')
  returning id
