  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 5/2000, contra la sentencia dictada por el Juez de Menores cabe recurso de:', 'El art. 41.1 LO 5/2000 prevé apelación ante la Audiencia Provincial en cinco días desde la notificación; el recurso de reforma en tres días es el previsto contra autos y providencias (art. 41.2).', 'gc_20_menores', (select id from public.topics where slug = 'gc-20-menores'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'Art. 41.1 LO 5/2000', '1. Contra la sentencia dictada por el Juez de Menores en el procedimiento regulado en esta Ley cabe recurso de apelación ante la correspondiente Audiencia Provincial, que se interpondrá ante el Juez que dictó aquélla en el plazo de cinco días a contar desde su notificación', null, 'd5e876ed540afa40749115bb6a61740b2c54b819011cf2b5960a96271cce54a0', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'd5e876ed540afa40749115bb6a61740b2c54b819011cf2b5960a96271cce54a0')
