with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 61 de la Ley Orgánica 5/2000, cuando el responsable de los hechos sea un menor de dieciocho años, ¿quiénes responden solidariamente con él de los daños y perjuicios causados?', 'El art. 61.3 LO 5/2000 establece la responsabilidad solidaria de padres, tutores, acogedores y guardadores legales o de hecho, por este orden, que el Juez puede moderar si no favorecieron la conducta con dolo o negligencia grave.', 'gc_20_menores', (select id from public.topics where slug = 'gc-20-menores'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'Art. 61.3 LO 5/2000', '3. Cuando el responsable de los hechos cometidos sea un menor de dieciocho años, responderán solidariamente con él de los daños y perjuicios causados sus padres, tutores, acogedores y guardadores legales o de hecho, por este orden.', null, '3fb03051ca2995bb3a864cc8a4f5b2c00fb0b4378984651959383afd41c307f5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '3fb03051ca2995bb3a864cc8a4f5b2c00fb0b4378984651959383afd41c307f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente sus padres, de forma subsidiaria.', false), ('B', 'Sus padres, tutores, acogedores y guardadores legales o de hecho, por este orden.', true), ('C', 'La entidad pública de protección de menores, en todo caso.', false), ('D', 'Sus padres y tutores, de forma mancomunada.', false)) as v(label, body, ok)
)
