with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 1 de la Ley Orgánica 1/2004, la violencia de género objeto de la ley es la que se ejerce sobre las mujeres por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad:', 'El art. 1.1 LO 1/2004 incluye la violencia ejercida por cónyuges o excónyuges y por quienes estén o hayan estado ligados a la mujer por relaciones similares de afectividad, aun sin convivencia.', 'gc_21_violencia_genero', (select id from public.topics where slug = 'gc-21-violencia-genero'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.1 LO 1/2004', 'se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.', null, 'be507a8ad0a6fa726280e03819b6a2b8d0d09cb0537f13e5023066f89070c34c', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'be507a8ad0a6fa726280e03819b6a2b8d0d09cb0537f13e5023066f89070c34c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Siempre que exista o haya existido convivencia.', false), ('B', 'Aun sin convivencia.', true), ('C', 'Siempre que la relación se haya inscrito en un registro público.', false), ('D', 'Solo si la relación ha durado al menos un año.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De acuerdo con el artículo 1.3 de la Ley Orgánica 1/2004, la violencia de género comprende:', 'El art. 1.3 LO 1/2004 define ampliamente la violencia de género: violencia física y psicológica, agresiones a la libertad sexual, amenazas, coacciones o privación arbitraria de libertad.', 'gc_21_violencia_genero', (select id from public.topics where slug = 'gc-21-violencia-genero'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.3 LO 1/2004', '3. La violencia de género a que se refiere la presente Ley comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad.', null, 'b391bd76ac6966c9f2eaf580fda06369cd15684c73d5ca2346f88c69f41900d8', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = 'b391bd76ac6966c9f2eaf580fda06369cd15684c73d5ca2346f88c69f41900d8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Únicamente los actos de violencia física que causen lesiones.', false), ('B', 'Los actos de violencia física y sexual, pero no las amenazas ni las coacciones.', false), ('C', 'Todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad.', true), ('D', 'Solo los actos de violencia cometidos en el domicilio común.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 1/2004, ¿se considera violencia de género la ejercida sobre los familiares o allegados menores de edad de la mujer?', 'El art. 1.4 LO 1/2004 (violencia vicaria) incluye la violencia sobre familiares o allegados menores de edad ejercida para causar perjuicio o daño a la mujer por cónyuges, excónyuges o parejas o exparejas.', 'gc_21_violencia_genero', (select id from public.topics where slug = 'gc-21-violencia-genero'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760'), 'Art. 1.4 LO 1/2004', '4. La violencia de género a que se refiere esta Ley también comprende la violencia que con el objetivo de causar perjuicio o daño a las mujeres se ejerza sobre sus familiares o allegados menores de edad por parte de las personas indicadas en el apartado primero.', null, '65545744b4113652ba429b26d76d3946d2eafe15e3893d4dcc26ed9d23256c37', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '65545744b4113652ba429b26d76d3946d2eafe15e3893d4dcc26ed9d23256c37')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No, porque la ley solo protege a la mujer.', false), ('B', 'Sí, cualquiera que sea el autor de la violencia.', false), ('C', 'Solo si los menores conviven con el agresor.', false), ('D', 'Sí, cuando se ejerza con el objetivo de causar perjuicio o daño a las mujeres por parte de las personas indicadas en el apartado primero del artículo 1.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
