  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 99 del Reglamento de Armas, respecto de la licencia de armas B para armas de fuego cortas de particulares, señale la respuesta correcta:', 'El art. 99 del Reglamento de Armas atribuye la concesión a la Dirección General de la Guardia Civil, con carácter restrictivo; la defensa de personas o bienes no basta por sí sola; validez de cinco años; nadie puede poseer más de una licencia B y cada licencia ampara un solo arma.', 'gc_22_armas_explosivos', (select id from public.topics where slug = 'gc-22-armas-explosivos'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'Art. 99 Reglamento de Armas', 'teniendo en cuenta que la razón de defensa de personas o bienes, por sí sola, no justifica la concesión de la licencia, cuya expedición tendrá carácter restrictivo, limitándose a supuestos de existencia de riesgo especial y de necesidad. […] Nadie podrá poseer más de una licencia B, y cada licencia no amparará más de un arma.', null, '59434797ce8190953538272a55d94b51b74cefbbfbd93bd69e303bc5b702dba6', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '59434797ce8190953538272a55d94b51b74cefbbfbd93bd69e303bc5b702dba6')
  returning id
), o as (
