  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La concede el Jefe de la Comandancia de la Guardia Civil y ampara hasta cinco armas.', false), ('B', 'La razón de defensa de personas o bienes, por sí sola, no justifica su concesión, y cada licencia no amparará más de un arma.', true), ('C', 'Tiene diez años de validez y se concede a quien acredite la defensa de su domicilio.', false), ('D', 'Una misma persona puede poseer hasta dos licencias B.', false)) as v(label, body, ok)
)
