)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('guardia-civil-cabos-guardias');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según la Ley Orgánica 12/1995, ¿qué son los «géneros o efectos estancados»?', 'El art. 1.11 LO 12/1995 define los géneros estancados por referencia al monopolio estatal e incluye las labores del tabaco; los «géneros prohibidos» se definen en el art. 1.12.', 'gc_23_contrabando', (select id from public.topics where slug = 'gc-23-contrabando'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-26836'), 'Art. 1.11 LO 12/1995', '11. “Géneros o efectos estancados”: los artículos, productos o sustancias cuya producción, adquisición, distribución o cualquiera otra actividad concerniente a los mismos sea atribuida por ley al Estado con carácter de monopolio, así como las labores del tabaco y todos aquellos a los que por ley se otorgue dicha condición.', null, '14db0f1b02ade50bcccfbf94aaa5dc9d4fa41e07614c045a0696e811441805b2', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '14db0f1b02ade50bcccfbf94aaa5dc9d4fa41e07614c045a0696e811441805b2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Los géneros cuya importación o exportación esté prohibida por tratado o convenio suscrito por España.', false), ('B', 'Los artículos, productos o sustancias cuya producción, adquisición, distribución o cualquier otra actividad concerniente a ellos sea atribuida por ley al Estado con carácter de monopolio, así como las labores del tabaco.', true), ('C', 'Las mercancías no comunitarias depositadas en áreas exentas a la espera de ser declaradas.', false), ('D', 'Los productos y tecnologías de doble uso sometidos a autorización.', false)) as v(label, body, ok)
)
