with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 10 de la Ley Orgánica 12/1995, el valor de los géneros estancados objeto de contrabando se fijará:', 'El art. 10.1 LO 12/1995 valora los géneros estancados por el precio máximo de venta al público; a falta de él, por la clase más similar, y solo si no es posible, por tasación pericial.', 'gc_23_contrabando', (select id from public.topics where slug = 'gc-23-contrabando'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-26836'), 'Art. 10.1 LO 12/1995', '1. Si se trata de géneros estancados, por el precio máximo de venta al público.', null, '5899a52d08e8bdb6c499fe82f431d65124a07cfe551b2715a77f275ae194f6cb', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '5899a52d08e8bdb6c499fe82f431d65124a07cfe551b2715a77f275ae194f6cb')
