with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 11 de la Ley Orgánica 12/1995, incurren en infracción administrativa de contrabando quienes realicen las conductas de los apartados 1 y 2 del artículo 2:', 'El art. 11.1 LO 12/1995 configura la infracción administrativa para las conductas dolosas o con cualquier grado de negligencia, cualquiera que sea el valor, cuando no sean delito.', 'gc_23_contrabando', (select id from public.topics where slug = 'gc-23-contrabando'), 2, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-26836'), 'Art. 11.1 LO 12/1995', 'que lleven a cabo las acciones u omisiones previstas en los apartados 1 y 2 del artículo 2 de la presente Ley, de forma dolosa o con cualquier grado de negligencia, cualquiera que sea el valor de los bienes, mercancías, géneros o efectos, cuando dichas conductas no constituyan delito.', null, '0e7097ff4906b6ba11f91948bc3f40cbd1f1b4f979aee7e6bcd393ff01bc367d', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '0e7097ff4906b6ba11f91948bc3f40cbd1f1b4f979aee7e6bcd393ff01bc367d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
