  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 11.2 de la Ley Orgánica 12/1995, con carácter general (fuera de los supuestos del artículo 2.2), es infracción administrativa de contrabando grave la referida a bienes cuyo valor esté:', 'El art. 11.2 LO 12/1995 clasifica las infracciones según el valor: leves, inferior a 37.500 €; graves, de 37.500 a 112.500 €; muy graves, superior a 112.500 €. Para los supuestos del art. 2.2 los tramos son 6.000 y 18.000 €, y para el tabaco 1.000 y 6.000 €.', 'gc_23_contrabando', (select id from public.topics where slug = 'gc-23-contrabando'), 3, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-26836'), 'Art. 11.2 LO 12/1995', 'b) Graves: entre los importes, ambos incluidos, de 37.500 euros a 112.500 euros', null, '46612fff4ec173c07101b682c23d9020b12fb94727b6839b69fd3f942cbacf20', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '46612fff4ec173c07101b682c23d9020b12fb94727b6839b69fd3f942cbacf20')
  returning id
), o as (
