  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Según el artículo 15 de la Ley Orgánica 12/1995, las infracciones administrativas de contrabando prescriben:', 'El art. 15 LO 12/1995 fija en cuatro años la prescripción de las infracciones (desde su comisión) y de las sanciones (desde el día siguiente a su firmeza).', 'gc_23_contrabando', (select id from public.topics where slug = 'gc-23-contrabando'), 1, 'es', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-26836'), 'Art. 15.1 LO 12/1995', '1. Las infracciones administrativas de contrabando prescriben a los cuatro años a contar desde el día de su comisión.', null, '2e0de40b1ce1ba6de9049b9b1b5afd6386ea5acfd4bb0b6c78e747c9408791c5', false
  where not exists (select 1 from public.questions where locale = 'es' and content_hash = '2e0de40b1ce1ba6de9049b9b1b5afd6386ea5acfd4bb0b6c78e747c9408791c5')
