insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 10/1995, de 23 de noviembre, del Código Penal (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-08a-penal-general', 'Tema 8. Derecho penal (I): parte general del Código Penal') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-08a-penal-general' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Título preliminar: garantías penales y aplicación de la ley penal (arts. 1-9 CP)"},{"n":"2","title":"Libro I, título I: la infracción penal (arts. 10-26 CP)"},{"n":"2.1","title":"Delitos, dolo, imprudencia, tentativa y causas de exención (arts. 10-20 CP)"},{"n":"2.2","title":"Circunstancias atenuantes, agravantes y mixta de parentesco (arts. 21-23 CP)"},{"n":"3","title":"Título II: personas criminalmente responsables (arts. 27-31 quinquies CP)"},{"n":"4","title":"Título III, capítulo I: las penas, sus clases y efectos (arts. 32-60 CP)"},{"n":"5","title":"Título IV: medidas de seguridad (arts. 95-108 CP)"},{"n":"6","title":"Título V, capítulos I y II: responsabilidad civil derivada de los delitos (arts. 109-122 CP)"},{"n":"7","title":"Título VII: extinción de la responsabilidad criminal y sus efectos (arts. 130-137 CP)"}]'::jsonb, '["Art. 1.1 Código Penal: «No será castigada ninguna acción ni omisión que no esté prevista como delito por ley anterior a su perpetración.»","Art. 2.2 Código Penal: «No obstante, tendrán efecto retroactivo aquellas leyes penales que favorezcan al reo, aunque al entrar en vigor hubiera recaído sentencia firme y el sujeto estuviese cumpliendo condena.»","Art. 5 Código Penal: «No hay pena sin dolo o imprudencia.»","Art. 10 Código Penal: «Son delitos las acciones y omisiones dolosas o imprudentes penadas por la ley.»","Art. 12 Código Penal: «Las acciones u omisiones imprudentes sólo se castigarán cuando expresamente lo disponga la Ley.»","Art. 15-16.1 Código Penal: «Son punibles el delito consumado y la tentativa de delito. […] Hay tentativa cuando el sujeto da principio a la ejecución del delito directamente por hechos exteriores, practicando todos o parte de los actos que objetivamente deberían producir el resultado, y sin embargo éste no se produce por causas independientes de la voluntad del autor.»","Art. 19 Código Penal: «Los menores de dieciocho años no serán responsables criminalmente con arreglo a este Código.»","Art. 20.4 Código Penal: «El que obre en defensa de la persona o derechos propios o ajenos, siempre que concurran los requisitos siguientes: Primero. Agresión ilegítima.»","Art. 27-29 Código Penal: «Son responsables criminalmente de los delitos los autores y los cómplices. […] Son autores quienes realizan el hecho por sí solos, conjuntamente o por medio de otro del que se sirven como instrumento. […] Son cómplices los que, no hallándose comprendidos en el artículo anterior, cooperan a la ejecución del hecho con actos anteriores o simultáneos.»","Art. 33.1 Código Penal: «En función de su naturaleza y duración, las penas se clasifican en graves, menos graves y leves.»","Art. 40.1 Código Penal: «La pena de inhabilitación absoluta tendrá una duración de seis a 20 años; las de inhabilitación especial, de tres meses a 20 años, y la de suspensión de empleo o cargo público, de tres meses a seis años.»","Art. 96.1 Código Penal: «Las medidas de seguridad que se pueden imponer con arreglo a este Código son privativas y no privativas de libertad.»","Art. 109 Código Penal: «La ejecución de un hecho descrito por la ley como delito obliga a reparar, en los términos previstos en las leyes, los daños y perjuicios por él causados. 2. El perjudicado podrá optar, en todo caso, por exigir la responsabilidad civil ante la Jurisdicción Civil.»","Art. 116.1 Código Penal: «Toda persona criminalmente responsable de un delito lo es también civilmente si del hecho se derivaren daños o perjuicios.»","Art. 130.1 Código Penal: «La responsabilidad criminal se extingue: 1.º Por la muerte del reo. 2.º Por el cumplimiento de la condena.»","Art. 131.1 Código Penal: «A los cinco, los demás delitos, excepto los delitos leves y los delitos de injurias y calumnias, que prescriben al año.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', null, null, null, null
  from public.topics t where t.slug = 'gc-08a-penal-general'
