insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 39/2015, de 1 de octubre, del Procedimiento Administrativo Común de las Administraciones Públicas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-10a-procedimiento-administrativo', 'Tema 10. Derecho administrativo (I): Ley 39/2015') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-10a-procedimiento-administrativo' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Título preliminar: objeto y ámbito subjetivo de la Ley 39/2015 (arts. 1-2)"},{"n":"2","title":"Los interesados: capacidad de obrar, concepto, representación, identificación y firma (título I, arts. 3-12)"},{"n":"3","title":"Actividad de las Administraciones: derechos, relación electrónica, registros y lenguas (título II, cap. I, arts. 13-28)"},{"n":"3.1","title":"Términos y plazos: obligación de resolver, silencio y cómputo (arts. 21-25 y 29-33)"},{"n":"4","title":"Los actos administrativos: requisitos, eficacia y notificación (título III, caps. I-II, arts. 34-46)"},{"n":"5","title":"Nulidad y anulabilidad (título III, cap. III, arts. 47-52)"},{"n":"6","title":"Procedimiento administrativo común: garantías, iniciación, ordenación, instrucción, finalización y ejecución (título IV, arts. 53-105)"},{"n":"6.1","title":"Tramitación simplificada (art. 96)"},{"n":"7","title":"Revisión de oficio (título V, cap. I, arts. 106-111)"},{"n":"8","title":"Recursos administrativos: alzada, reposición y extraordinario de revisión (título V, cap. II, arts. 112-126)"},{"n":"9","title":"Iniciativa legislativa y potestad reglamentaria (título VI, arts. 127-133)"}]'::jsonb, '["Art. 1.1 Ley 39/2015: «La presente Ley tiene por objeto regular los requisitos de validez y eficacia de los actos administrativos, el procedimiento administrativo común a todas las Administraciones Públicas, incluyendo el sancionador y el de reclamación de responsabilidad de las Administraciones Públicas, así como los principios a los que se ha de ajustar el ejercicio de la iniciativa legislativa y la potestad reglamentaria.»","Art. 4.1 Ley 39/2015: «Se consideran interesados en el procedimiento administrativo: a) Quienes lo promuevan como titulares de derechos o intereses legítimos individuales o colectivos. b) Los que, sin haber iniciado el procedimiento, tengan derechos que puedan resultar afectados por la decisión que en el mismo se adopte. c) Aquellos cuyos intereses legítimos, individuales o colectivos, puedan resultar afectados por la resolución y se personen en el procedimiento en tanto no haya recaído resolución definitiva.»","Art. 14.1 Ley 39/2015: «Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no, salvo que estén obligadas a relacionarse a través de medios electrónicos con las Administraciones Públicas.»","Art. 21.1 Ley 39/2015: «La Administración está obligada a dictar resolución expresa y a notificarla en todos los procedimientos cualquiera que sea su forma de iniciación.»","Art. 21.2-3 Ley 39/2015: «Este plazo no podrá exceder de seis meses salvo que una norma con rango de Ley establezca uno mayor o así venga previsto en el Derecho de la Unión Europea. 3. Cuando las normas reguladoras de los procedimientos no fijen el plazo máximo, éste será de tres meses.»","Art. 24.2 Ley 39/2015: «La estimación por silencio administrativo tiene a todos los efectos la consideración de acto administrativo finalizador del procedimiento. La desestimación por silencio administrativo tiene los solos efectos de permitir a los interesados la interposición del recurso administrativo o contencioso-administrativo que resulte procedente.»","Art. 30.2 Ley 39/2015: «Siempre que por Ley o en el Derecho de la Unión Europea no se exprese otro cómputo, cuando los plazos se señalen por días, se entiende que éstos son hábiles, excluyéndose del cómputo los sábados, los domingos y los declarados festivos.»","Art. 39.1 Ley 39/2015: «Los actos de las Administraciones Públicas sujetos al Derecho Administrativo se presumirán válidos y producirán efectos desde la fecha en que se dicten, salvo que en ellos se disponga otra cosa.»","Art. 40.2 Ley 39/2015: «Toda notificación deberá ser cursada dentro del plazo de diez días a partir de la fecha en que el acto haya sido dictado»","Art. 43.2 Ley 39/2015: «Cuando la notificación por medios electrónicos sea de carácter obligatorio, o haya sido expresamente elegida por el interesado, se entenderá rechazada cuando hayan transcurrido diez días naturales desde la puesta a disposición de la notificación sin que se acceda a su contenido.»","Art. 54 Ley 39/2015: «Los procedimientos podrán iniciarse de oficio o a solicitud del interesado.»","Art. 82.2 Ley 39/2015: «Los interesados, en un plazo no inferior a diez días ni superior a quince, podrán alegar y presentar los documentos y justificaciones que estimen pertinentes.»","Art. 84.1 Ley 39/2015: «Pondrán fin al procedimiento la resolución, el desistimiento, la renuncia al derecho en que se funde la solicitud, cuando tal renuncia no esté prohibida por el ordenamiento jurídico, y la declaración de caducidad.»","Art. 107.2 Ley 39/2015: «La declaración de lesividad no podrá adoptarse una vez transcurridos cuatro años desde que se dictó el acto administrativo y exigirá la previa audiencia de cuantos aparezcan como interesados en el mismo, en los términos establecidos por el artículo 82.»","Art. 122.1 Ley 39/2015: «El plazo para la interposición del recurso de alzada será de un mes, si el acto fuera expreso. Transcurrido dicho plazo sin haberse interpuesto el recurso, la resolución será firme a todos los efectos.»","Art. 124.2 Ley 39/2015: «El plazo máximo para dictar y notificar la resolución del recurso será de un mes.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565', null, null, null, null
  from public.topics t where t.slug = 'gc-10a-procedimiento-administrativo'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
