 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 4/2015, de 30 de marzo, de protección de la seguridad ciudadana (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-13-seguridad-publica-privada', 'Tema 13. Seguridad pública (LO 4/2015) y seguridad privada (Ley 5/2014)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-13-seguridad-publica-privada' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"LO 4/2015: disposiciones generales y autoridades competentes (cap. I, arts. 1-7)"},{"n":"2","title":"Documentación e identificación personal: DNI y pasaporte (cap. II, arts. 8-13)"},{"n":"3","title":"Potestades generales de policía de seguridad: identificación, registros y controles (cap. III, sec. 1.ª, arts. 14-22)"},{"n":"4","title":"Reuniones y manifestaciones (cap. III, sec. 2.ª, arts. 23-24)"},{"n":"5","title":"Potestades especiales de policía administrativa: armas y explosivos (cap. IV, arts. 25-29)"},{"n":"6","title":"Régimen sancionador: responsables, órganos, infracciones, sanciones y procedimiento (cap. V, arts. 30-54)"},{"n":"7","title":"Ley 5/2014: disposiciones generales, actividades y competencias (título preliminar, arts. 1-13)"},{"n":"8","title":"Coordinación con las Fuerzas y Cuerpos de Seguridad (título I, arts. 14-16)"},{"n":"9","title":"Empresas de seguridad privada y despachos de detectives (título II, arts. 17-25)"},{"n":"10","title":"Personal de seguridad privada: habilitación y funciones (título III, arts. 26-37)"},{"n":"11","title":"Servicios y medidas de seguridad; control administrativo (títulos IV y V, arts. 38-55)"}]'::jsonb, '["Art. 1.1 LO 4/2015: «La seguridad ciudadana es un requisito indispensable para el pleno ejercicio de los derechos fundamentales y las libertades públicas, y su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado, con sujeción a la Constitución y a las Leyes.»","Art. 8.1 LO 4/2015: «El Documento Nacional de Identidad es un documento público y oficial y tendrá la protección que a estos otorgan las leyes. Es el único documento con suficiente valor por sí solo para la acreditación, a todos los efectos, de la identidad y los datos personales de su titular.»","Art. 9.1 LO 4/2015: «El Documento Nacional de Identidad es obligatorio a partir de los catorce años.»","Art. 16.2 LO 4/2015: «a los solos efectos de su identificación y por el tiempo estrictamente necesario, que en ningún caso podrá superar las seis horas.»","Art. 23.2 LO 4/2015: «Las medidas de intervención para el mantenimiento o el restablecimiento de la seguridad ciudadana en reuniones y manifestaciones serán graduales y proporcionadas a las circunstancias. La disolución de reuniones y manifestaciones constituirá el último recurso.»","Art. 28.2 LO 4/2015: «La intervención de armas, explosivos, cartuchería y artículos pirotécnicos corresponde al Ministerio del Interior, que la ejerce a través de la Dirección General de la Guardia Civil»","Art. 32.1 LO 4/2015: «a) El Ministro del Interior, para la sanción de las infracciones muy graves en grado máximo. b) El Secretario de Estado de Seguridad, para la sanción de infracciones muy graves en grado medio y en grado mínimo. c) Los Delegados del Gobierno en las comunidades autónomas y en las Ciudades de Ceuta y Melilla, para la sanción de las infracciones graves y leves.»","Art. 38.1 LO 4/2015: «Las infracciones administrativas tipificadas en esta Ley prescribirán a los seis meses, al año o a los dos años de haberse cometido, según sean leves, graves o muy graves, respectivamente.»","Art. 39.1 LO 4/2015: «Las infracciones muy graves se sancionarán con multa de 30.001 a 600.000 euros; las graves, con multa de 601 a 30.000 euros, y las leves, con multa de 100 a 600 euros.»","Art. 1.1 Ley 5/2014: «Todas estas actividades tienen la consideración de complementarias y subordinadas respecto de la seguridad pública.»","Art. 18.3 Ley 5/2014: «La validez de la autorización o de la declaración responsable será indefinida.»","Art. 26.1 Ley 5/2014: «Únicamente puede ejercer funciones de seguridad privada el personal de seguridad privada, que estará integrado por los vigilantes de seguridad y su especialidad de vigilantes de explosivos, los escoltas privados, los guardas rurales y sus especialidades de guardas de caza y guardapescas marítimos, los jefes de seguridad, los directores de seguridad y los detectives privados.»","Art. 27.3 Ley 5/2014: «La habilitación de todo el personal de seguridad privada corresponderá a la Dirección General de la Policía, excepto la de los guardas rurales y sus especialidades que corresponderá a la Dirección General de la Guardia Civil.»","Art. 31 Ley 5/2014: «Se considerarán agresiones y desobediencias a agentes de la autoridad las que se cometan contra el personal de seguridad privada, debidamente identificado, cuando desarrolle actividades de seguridad privada en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', null, null, null, 'Otras normas citadas: Ley 5/2014 (https://www.boe.es/buscar/act.php?id=BOE-A-2014-3649)'
