 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-20-menores', 'Tema 20. Responsabilidad penal de los menores (LO 5/2000)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-20-menores' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Título preliminar: ámbito de aplicación por edad (art. 1)"},{"n":"2","title":"Título I: competencia de los Jueces de Menores, menores de catorce años, víctimas y Ministerio Fiscal (arts. 2-6)"},{"n":"3","title":"Título II: las medidas (arts. 7-15)"},{"n":"3.1","title":"Catálogo de medidas y principio acusatorio (arts. 7-8)"},{"n":"3.2","title":"Duración de las medidas y reglas especiales (arts. 9-11)"},{"n":"3.3","title":"Modificación, mayoría de edad y prescripción (arts. 13-15)"},{"n":"4","title":"Título III: instrucción del procedimiento por el Ministerio Fiscal (arts. 16-30)"},{"n":"4.1","title":"Detención de los menores (art. 17)"},{"n":"4.2","title":"Desistimiento y conciliación o reparación (arts. 18-19)"},{"n":"4.3","title":"Medidas cautelares (arts. 28-29)"},{"n":"5","title":"Títulos IV a VI: audiencia, sentencia y recursos (arts. 31-42)"},{"n":"6","title":"Título VII: ejecución de las medidas (arts. 43-60)"},{"n":"7","title":"Título VIII: responsabilidad civil (arts. 61-64)"}]'::jsonb, '["Art. 1.1 LO 5/2000: «Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de catorce años y menores de dieciocho por la comisión de hechos tipificados como delitos o faltas en el Código Penal o las leyes penales especiales.»","Art. 3 LO 5/2000: «Cuando el autor de los hechos mencionados en los artículos anteriores sea menor de catorce años, no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores previstas en el Código Civil y demás disposiciones vigentes.»","Art. 5.3 LO 5/2000: «Las edades indicadas en el articulado de esta Ley se han de entender siempre referidas al momento de la comisión de los hechos, sin que el haberse rebasado las mismas antes del comienzo del procedimiento o durante la tramitación del mismo tenga incidencia alguna sobre la competencia atribuida por esta misma Ley a los Jueces y Fiscales de Menores.»","Art. 7.1 LO 5/2000: «Las medidas que pueden imponer los Jueces de Menores, ordenadas según la restricción de derechos que suponen, son las siguientes: a) Internamiento en régimen cerrado.»","Art. 8 LO 5/2000: «El Juez de Menores no podrá imponer una medida que suponga una mayor restricción de derechos ni por un tiempo superior a la medida solicitada por el Ministerio Fiscal o por el acusador particular.»","Art. 9.3 LO 5/2000: «La duración de las medidas no podrá exceder de dos años, computándose, en su caso, a estos efectos el tiempo ya cumplido por el menor en medida cautelar, conforme a lo dispuesto en el artículo 28.5 de la presente Ley. La medida de prestaciones en beneficio de la comunidad no podrá superar las cien horas. La medida de permanencia de fin de semana no podrá superar los ocho fines de semana.»","Art. 9.4 LO 5/2000: «Las acciones u omisiones imprudentes no podrán ser sancionadas con medidas de internamiento en régimen cerrado.»","Art. 15.2 LO 5/2000: «Las medidas que tengan una duración superior a los dos años prescribirán a los tres años. Las restantes medidas prescribirán a los dos años, excepto la amonestación, las prestaciones en beneficio de la comunidad y la permanencia de fin de semana, que prescribirán al año.»","Art. 16.1 LO 5/2000: «Corresponde al Ministerio Fiscal la instrucción de los procedimientos por los hechos a los que se refiere el artículo 1 de esta Ley.»","Art. 17.3 LO 5/2000: «Mientras dure la detención, los menores deberán hallarse custodiados en dependencias adecuadas y separadas de las que se utilicen para los mayores de edad, y recibirán los cuidados, protección y asistencia social, psicológica, médica y física que requieran, habida cuenta de su edad, sexo y características individuales.»","Art. 17.4 LO 5/2000: «La detención de un menor por funcionarios de policía no podrá durar más tiempo del estrictamente necesario para la realización de las averiguaciones tendentes al esclarecimiento de los hechos, y, en todo caso, dentro del plazo máximo de veinticuatro horas, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal.»","Art. 17.5 LO 5/2000: «Cuando el detenido sea puesto a disposición del Ministerio Fiscal, éste habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención, sobre la puesta en libertad del menor, sobre el desistimiento al que se refiere el artículo siguiente, o sobre la incoación del expediente, poniendo a aquél a disposición del Juez de Menores competente e instando del mismo las oportunas medidas cautelares, con arreglo a lo establecido en el artículo 28.»","Art. 28.3 LO 5/2000: «El tiempo máximo de la medida cautelar de internamiento será de seis meses, y podrá prorrogarse, a instancia del Ministerio Fiscal, previa audiencia del letrado del menor y mediante auto motivado, por otros tres meses como máximo.»","Art. 38 LO 5/2000: «Finalizada la audiencia, el Juez de Menores dictará sentencia en un plazo máximo de cinco días.»","Art. 55.1 LO 5/2000: «Toda la actividad de los centros en los que se ejecuten medidas de internamiento estará inspirada por el principio de que el menor internado es sujeto de derecho y continúa formando parte de la sociedad.»","Art. 61.3 LO 5/2000: «Cuando el responsable de los hechos cometidos sea un menor de dieciocho años, responderán solidariamente con él de los daños y perjuicios causados sus padres, tutores, acogedores y guardadores legales o de hecho, por este orden.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641', null, null, null, null
  from public.topics t where t.slug = 'gc-20-menores'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
