insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 137/1993, de 29 de enero, Reglamento de Armas (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gc-22-armas-explosivos', 'Tema 22. Armas y explosivos: Reglamento de Armas y Reglamento de Explosivos') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-civil-cabos-guardias') and t.slug = 'gc-22-armas-explosivos' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Reglamento de Armas (RD 137/1993): objeto, ámbito y definiciones (arts. 1-2)"},{"n":"2","title":"Clasificación de las armas reglamentadas: categorías 1.ª a 9.ª (art. 3)"},{"n":"3","title":"Armas prohibidas y armas de guerra (arts. 4-6)"},{"n":"4","title":"Intervención e inspección: Guardia Civil y otros ministerios (arts. 7-9)"},{"n":"5","title":"Documentación de la titularidad: guías de pertenencia y revista (arts. 88-95)"},{"n":"6","title":"Licencias, autorizaciones especiales y tarjetas de armas (arts. 96-109)"},{"n":"7","title":"Disposiciones comunes sobre tenencia y uso de armas (arts. 144-149)"},{"n":"8","title":"Reglamento de Explosivos (RD 130/2017): objeto, ámbito y competencias administrativas (arts. 1-2)"},{"n":"9","title":"Clasificación de explosivos: divisiones de riesgo (arts. 8-9)"},{"n":"10","title":"Depósitos y polvorines (arts. 56-57)"},{"n":"11","title":"Comercialización y uso de explosivos (arts. 108-125)"},{"n":"12","title":"Transporte de explosivos (arts. 146-151)"}]'::jsonb, '["Art. 1.4 Reglamento de Armas: «Quedan excluidos del ámbito de aplicación de este Reglamento, y se regirán por la normativa especial dictada al efecto, la adquisición, tenencia y uso de armas por las Fuerzas Armadas, las Fuerzas y Cuerpos de Seguridad y el Centro Nacional de Inteligencia.»","Art. 3 Reglamento de Armas: «1.ª categoría: Armas de fuego cortas: Comprende las pistolas y revólveres.»","Art. 6.1 Reglamento de Armas: «Se consideran armas de guerra, quedando en consecuencia prohibidos su adquisición, tenencia y uso por particulares: a) Armas de fuego o sistemas de armas de fuego de calibre igual o superior a 20 milímetros.»","Art. 8.1 Reglamento de Armas: «Para efectuar la intervención, la Guardia Civil procederá a inspeccionar, cuantas veces lo considere preciso y sin necesidad de previo aviso, los diferentes locales de las fábricas, talleres, depósitos o comercios de armas, vehículos que las transporten, lugares de utilización de éstas y todos aquellos que se relacionen directamente con las actividades realizadas en los mismos.»","Art. 90.1 Reglamento de Armas: «Las armas que precisen guía de pertenencia, pasarán revista cada cinco años. Las revistas se pasarán en el momento de presentar las solicitudes de renovación de las correspondientes licencias de armas de los titulares de aquellas.»","Art. 96.2 Reglamento de Armas: «La tenencia y el uso de las armas de las categorías 1.ª, 2.ª y 3.ª precisará de licencia de armas.»","Art. 99.1 Reglamento de Armas: «La licencia de armas B solamente podrá ser expedida a quienes tengan necesidad de obtenerla, y será competente para concederla la Dirección General de la Guardia Civil.»","Art. 101.1-2 Reglamento de Armas: «Su número no excederá de seis escopetas o de seis armas largas rayadas para tiro deportivo, ni de doce armas en total. 2. Nadie podrá poseer más de una licencia E, que tendrá cinco años de validez.»","Art. 144.1.c) Reglamento de Armas: «A declarar, inmediatamente, en la Intervención de Armas correspondiente, la pérdida, destrucción, robo o sustracción de las armas o de su documentación.»","Art. 148.2 Reglamento de Armas: «Dichos agentes podrán proceder a la ocupación temporal de las mismas, depositándolas en una Intervención de Armas de la Guardia Civil, incluso de las que se lleven con licencia, con objeto de prevenir la comisión de cualquier delito o garantizar la seguridad de las personas o de las cosas»","Art. 2.1 Reglamento de Explosivos: «Todas las actividades reglamentadas quedan bajo la intervención administrativa del Estado.»","Art. 56.1 Reglamento de Explosivos: «Se entenderá por depósito el recinto o lugar que alberga uno o más polvorines.»","Art. 109.3 Reglamento de Explosivos: «Queda expresamente prohibido el envío de explosivos por correspondencia vía postal.»","Art. 119.1 Reglamento de Explosivos: «La autorización para la utilización habitual de explosivos con ámbito nacional será otorgada por la Dirección General de la Guardia Civil, previo informe favorable de la Dirección General de Política Energética y Minas. Esta autorización tendrá un plazo de validez de cinco años»","Art. 147.4 Reglamento de Explosivos: «Durante las operaciones comprendidas en el transporte de las materias reglamentadas estará prohibido fumar, portar cerillas o cualquier otro dispositivo productor de llamas, sustancias que puedan inflamarse, armas de fuego y cartuchería, salvo el armamento reglamentario correspondiente a los vigilantes de explosivos del transporte.»","Art. 148 Reglamento de Explosivos: «En todo momento, los productos regulados se encontrarán sometidos a la inspección de la autoridad y, bajo la protección de vigilantes de explosivos, conforme a lo dispuesto en la ITC número 1.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202', null, null, null, 'Otras normas citadas: Reglamento de Explosivos (https://www.boe.es/buscar/act.php?id=BOE-A-2017-2313)'
  from public.topics t where t.slug = 'gc-22-armas-explosivos'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
